) v(slug, path, sort) join public.classes c on coalesce(c.site_slug, c.follows) = v.slug and c.owner_kind = 'main' on conflict (class_id, path) do update set sort = excluded.sort;
commit;
select (select count(*) from public.lessons where external_id like 'CKS8-%') as lessons, (select count(*) from public.lesson_specs where lesson like 'CKS8-%') as specs, (select count(*) from public.classes where coalesce(site_slug, follows) like 'cks8-%') as classes, (select count(*) from public.quizzes where title like 'Stage 8 % · Checkpoint-style questions') as question_sets, (select count(*) from public.quizzes where title like 'Stage 8 % · Checkpoint-style examination%') as exams;
