insert into public.lessons (id, topic_id, title, summary, url, external_id, max_marks, minutes, sort_order) values ('a97d9f3d-ac12-5c21-9a42-25f90928079e', 'f6270714-d8ad-583e-a084-b8f66212d8e8', 'Unit 1 The skeleton, joints and muscles: Joints and muscles that move us', 'Stage 8 Biology · Objectives 8Bs.01', '/cks8-bio-1/', 'CKS8-BIO-L1', 23, 60, 10) on conflict (external_id) do update set title = excluded.title, summary = excluded.summary, url = excluded.url, max_marks = excluded.max_marks, minutes = excluded.minutes, topic_id = excluded.topic_id, sort_order = excluded.sort_order;
insert into public.lesson_specs (lesson, title, spec, updated_at) values ('CKS8-BIO-L1', 'Unit 1 The skeleton, joints and muscles: Joints and muscles that move us', '{"marks": {"1": [{"kind": "choice", "id": "q1_0", "q": "Q1", "max": 4, "n": 4, "ans": ["Protection", "Support", "Making blood cells", "Movement"], "tip": "Four jobs."}], "2": [{"kind": "choice", "id": "q2_0", "q": "Q2", "max": 4, "n": 4, "ans": ["Hinge", "Ball-and-socket", "Hinge", "Ball-and-socket"], "tip": "One direction or many?"}, {"kind": "choice", "id": "q2_1", "q": "Q3", "max": 4, "n": 4, "ans": ["Ligament", "Tendon", "Cartilage", "Synovial fluid"], "tip": "Bone–bone, muscle–bone."}], "3": [{"kind": "choice", "id": "q3_0", "q": "Q4", "max": 4, "n": 4, "ans": ["Contracts", "Relaxes", "Contracts", "Relaxes"], "tip": "Who is pulling?"}, {"kind": "text", "id": "q3_1", "q": "Q5", "max": 2, "pts": [["only pull", "cannot push", "contract"], ["back", "opposite", "other direction", "pair"]], "tips": ["Pull only."]}], "4": [{"kind": "text", "id": "q4_0", "q": "Q6", "max": 2, "pts": [["rub", "friction", "grind"], ["bone", "pain", "nerve"]], "tips": ["What does cartilage normally do?"]}], "5": [{"kind": "text", "id": "q5_0", "q": "Q7", "max": 3, "pts": [["pull", "shorten", "front band", "biceps"], ["other band", "stretch", "relax", "triceps"], ["elastic", "push", "not real", "no cartilage", "ligament", "one direction", "limitation"]], "tips": ["Use the bands as muscles."]}]}, "models": {"1": [["Q1", "Skull: protection; backbone: support; marrow: blood cells; muscles pulling: movement."]], "2": [["Q2", "Elbow and knee: hinge. Hip and shoulder: ball-and-socket."], ["Q3", "Ligament; tendon; cartilage; synovial fluid."]], "3": [["Q4", "Bending: biceps contracts, triceps relaxes. Straightening: the reverse."], ["Q5", "Muscles can only pull (contract), they cannot push [1], so a second muscle is needed to pull the bone back the other way [1]."]], "4": [["Q6", "Without cartilage the bone ends rub against each other, causing friction [1] that damages the bone and causes pain [1]."]], "5": [["Q7", "Shorten (pull) the band on the front, like the biceps contracting, to bend the joint [1]; the band at the back stretches, like the triceps relaxing [1]; a limitation: elastic bands spring back by themselves, but real muscles cannot push, and there is no cartilage or fluid [1]."]], "6": [["Exit ticket", "The triceps."]]}, "labels": {"q3_1": "Q5", "q4_0": "Q6", "q5_0": "Q7", "q6_0": "Exit ticket", "s6rev": "Revision plan", "s6q": "Question"}, "questions": {"Q1": "Which job of the skeleton?", "Q2": "Hinge or ball-and-socket?", "Q3": "Which part of the joint?", "Q4": "Contracts or relaxes?", "Q5": "Explain why muscles at a joint must work in pairs.", "Q6": "Suggest why a person with worn cartilage in the knee finds walking painful.", "Q7": "A student models the arm with two pieces of card (bones), a split pin (joint) and two elastic bands (muscles). Describe how to show the arm bending and give one limitation of the model."}}'::jsonb, now()) on conflict (lesson) do update set title = excluded.title, spec = excluded.spec, updated_at = now();
