insert into public.lesson_specs (lesson, title, spec, updated_at) values ('CKS8-BIO-L2', 'Unit 2 Blood, breathing and gas exchange: Blood, breathing and gas exchange', '{"marks": {"1": [{"kind": "choice", "id": "q1_0", "q": "Q1", "max": 4, "n": 4, "ans": ["Red blood cell", "Platelet", "White blood cell", "Plasma"], "tip": "Four parts, four jobs."}], "2": [{"kind": "choice", "id": "q2_0", "q": "Q2", "max": 4, "n": 4, "ans": ["3rd", "1st", "4th", "2nd"], "tip": "Big tubes to tiny sacs."}, {"kind": "text", "id": "q2_1", "q": "Q3", "max": 2, "pts": [["diaphragm+contract", "diaphragm+flatten", "diaphragm+down"], ["ribs+up", "ribs+out"]], "tips": ["Make the chest bigger."]}], "3": [{"kind": "text", "id": "q3_0", "q": "Q4", "max": 3, "pts": [["surface area", "many"], ["thin", "one cell"], ["blood supply", "capillaries", "moist"]], "tips": ["Area, distance, supply."]}, {"kind": "choice", "id": "q3_1", "q": "Q5", "max": 2, "n": 2, "ans": ["Alveoli → blood", "Blood → alveoli"], "tip": "High to low."}], "4": [{"kind": "text", "id": "q4_0", "q": "Q6", "max": 2, "pts": [["breathing+air", "breathing+lungs", "movement of air"], ["respiration+energy", "reaction", "cells", "glucose"]], "tips": ["Movement or reaction?"]}], "5": [{"kind": "text", "id": "q5_0", "q": "Q7", "max": 3, "pts": [["surface area"], ["less oxygen", "oxygen", "diffuse"], ["blood", "cells", "respiration", "energy"]], "tips": ["Area → oxygen → energy."]}]}, "models": {"1": [["Q1", "Red cells: oxygen; platelets: clotting; white cells: infection; plasma: dissolved substances."]], "2": [["Q2", "Trachea → bronchus → bronchiole → alveolus."], ["Q3", "The diaphragm contracts and flattens [1]; the ribs move up and out, increasing the volume of the chest [1]."]], "3": [["Q4", "Millions of alveoli give a very large surface area [1]; their walls are only one cell thick, so the diffusion distance is short [1]; they are surrounded by many capillaries (and are moist) [1]."], ["Q5", "Oxygen into the blood; carbon dioxide out of it."]], "4": [["Q6", "Breathing is the movement of air into and out of the lungs [1]; respiration is a chemical reaction in cells that releases energy from glucose [1]."]], "5": [["Q7", "Fewer, larger air spaces have a smaller surface area [1], so less oxygen diffuses into the blood [1]; cells get less oxygen for respiration, so the person feels breathless and tired [1]."]], "6": [["Exit ticket", "Oxygen."]]}, "labels": {"q2_1": "Q3", "q3_0": "Q4", "q4_0": "Q6", "q5_0": "Q7", "q6_0": "Exit ticket", "s6rev": "Revision plan", "s6q": "Question"}, "questions": {"Q1": "Which part of the blood?", "Q2": "Put the path of air in order.", "Q3": "Describe what the diaphragm and ribs do when you breathe in.", "Q4": "Give three ways the alveoli are adapted for efficient gas exchange.", "Q5": "Which way does each gas diffuse?", "Q6": "Explain the difference between breathing and respiration.", "Q7": "Emphysema destroys the walls between alveoli, making fewer, larger air spaces. Explain why people with emphysema become breathless."}}'::jsonb, now()) on conflict (lesson) do update set title = excluded.title, spec = excluded.spec, updated_at = now();
