insert into public.lesson_specs (lesson, title, spec, updated_at) values ('CKS8-BIO-L3', 'Unit 3 Diet and health: A balanced diet for a healthy life', '{"marks": {"1": [{"kind": "choice", "id": "q1_0", "q": "Q1", "max": 6, "n": 6, "ans": ["Carbohydrate", "Protein", "Vitamin C", "Calcium", "Iron", "Fibre"], "tip": "Match job to nutrient."}], "2": [{"kind": "text", "id": "q2_0", "q": "Q2", "max": 3, "pts": [["370"], ["340"], ["710"]], "tips": ["Fat, carbohydrate, total."]}], "3": [{"kind": "choice", "id": "q3_0", "q": "Q3", "max": 4, "n": 4, "ans": ["Vitamin C", "Iron", "Protein", "Calcium or vitamin D"], "tip": "Disease → missing nutrient."}, {"kind": "text", "id": "q3_1", "q": "Q4", "max": 2, "pts": [["stored", "excess", "extra"], ["fat"]], "tips": ["Where does extra energy go?"]}], "4": [{"kind": "text", "id": "q4_0", "q": "Q5", "max": 2, "pts": [["tar", "cancer", "lung"], ["carbon monoxide", "oxygen", "nicotine", "heart", "addict"]], "tips": ["Two chemicals, two effects."]}], "5": [{"kind": "text", "id": "q5_0", "q": "Q6", "max": 4, "pts": [["protein"], ["growth", "repair", "muscle"], ["carbohydrate", "energy"], ["iron", "calcium", "water"]], "tips": ["Growth, energy, blood, bones."]}]}, "models": {"1": [["Q1", "Carbohydrate; protein; vitamin C; calcium; iron; fibre."]], "2": [["Q2", "Fat: 10 × 37 = 370 kJ [1]; carbohydrate: 20 × 17 = 340 kJ [1]; total = 710 kJ [1]."]], "3": [["Q3", "Scurvy: vitamin C; anaemia: iron; kwashiorkor: protein; rickets: calcium/vitamin D."], ["Q4", "The extra energy is not used, so it is stored [1] as fat in the body, which builds up over time [1]."]], "4": [["Q5", "Tar in smoke can cause lung cancer [1]; carbon monoxide reduces the oxygen carried by the blood (and nicotine is addictive and harms the heart) [1]."]], "5": [["Q6", "More protein [1] for growth and repair of muscles [1]; more carbohydrates for energy for training [1]; iron for red blood cells (and calcium for bones, water to replace sweat) [1]."]], "6": [["Exit ticket", "Growth and repair of cells."]]}, "labels": {"q2_0": "Q2", "q3_1": "Q4", "q4_0": "Q5", "q5_0": "Q6", "q6_0": "Exit ticket", "s6rev": "Revision plan", "s6q": "Question"}, "questions": {"Q1": "Which nutrient?", "Q2": "A snack contains 10 g of fat and 20 g of carbohydrate. Using 37 kJ/g for fat and 17 kJ/g for carbohydrate, calculate the energy it provides.", "Q3": "Which deficiency?", "Q4": "Explain how eating more energy than you use can lead to obesity.", "Q5": "Explain two ways smoking can damage health.", "Q6": "A 13-year-old athlete is growing fast and training every day. Suggest which nutrients she needs more of and explain why."}}'::jsonb, now()) on conflict (lesson) do update set title = excluded.title, spec = excluded.spec, updated_at = now();
