insert into public.lessons (id, topic_id, title, summary, url, external_id, max_marks, minutes, sort_order) values ('39cbd917-e0bd-51a5-887d-ad604a16b6b9', '18ac6b04-8c8a-5bcd-895c-8f9f55db37df', 'Unit 4 Aerobic respiration: Aerobic respiration: releasing energy', 'Stage 8 Biology · Objectives 8Bp.04, 8Bp.05', '/cks8-bio-4/', 'CKS8-BIO-L4', 19, 60, 40) on conflict (external_id) do update set title = excluded.title, summary = excluded.summary, url = excluded.url, max_marks = excluded.max_marks, minutes = excluded.minutes, topic_id = excluded.topic_id, sort_order = excluded.sort_order;
insert into public.lesson_specs (lesson, title, spec, updated_at) values ('CKS8-BIO-L4', 'Unit 4 Aerobic respiration: Aerobic respiration: releasing energy', '{"marks": {"1": [{"kind": "choice", "id": "q1_0", "q": "Q1", "max": 4, "n": 4, "ans": ["False", "True", "True", "False"], "tip": "Every living cell respires."}], "2": [{"kind": "choice", "id": "q2_0", "q": "Q2", "max": 3, "n": 3, "ans": ["oxygen", "carbon dioxide", "water"], "tip": "Reverse of photosynthesis."}, {"kind": "text", "id": "q2_1", "q": "Q3", "max": 2, "pts": [["steps", "gradual", "slowly", "small"], ["enzymes", "not all at once", "burning", "heat"]], "tips": ["Compare with burning."]}], "3": [{"kind": "text", "id": "q3_0", "q": "Q4", "max": 3, "pts": [["respir"], ["energy", "heat"], ["control", "compare", "dead", "fair"]], "tips": ["Living vs dead."]}], "4": [{"kind": "text", "id": "q4_0", "q": "Q5", "max": 3, "pts": [["more respiration", "respire faster", "more energy"], ["more oxygen", "oxygen"], ["carbon dioxide", "remove"]], "tips": ["Muscles need more."]}], "5": [{"kind": "text", "id": "q5_0", "q": "Q6", "max": 4, "pts": [["temperature", "water bath"], ["bubbles", "gas", "carbon dioxide", "limewater", "syringe"], ["same", "mass of yeast", "sugar", "volume"], ["time", "per minute", "repeat"]], "tips": ["Change, measure, control."]}]}, "models": {"1": [["Q1", "Respiration happens in every living cell, including plant cells, and releases energy from glucose using oxygen."]], "2": [["Q2", "glucose + oxygen → carbon dioxide + water."], ["Q3", "The energy is released in many small steps [1] controlled by enzymes, not all at once as heat and light like burning [1]."]], "3": [["Q4", "The germinating peas respire [1], releasing energy as heat, so the temperature rises by 6 °C [1]; the boiled (dead) peas are a control to show the rise is caused by living peas [1]."]], "4": [["Q5", "Muscles respire faster to release more energy [1], so they need more oxygen delivered quickly [1] and more carbon dioxide must be removed [1]."]], "5": [["Q6", "Change the temperature using water baths, e.g. 20–50 °C [1]; measure the rate by counting carbon dioxide bubbles (or gas volume in a syringe) [1]; keep the mass of yeast, sugar concentration and volume the same [1]; count for a fixed time, e.g. 1 minute, and repeat [1]."]], "6": [["Exit ticket", "glucose + oxygen → carbon dioxide + water."]]}, "labels": {"q2_1": "Q3", "q3_0": "Q4", "q4_0": "Q5", "q5_0": "Q6", "q6_0": "Exit ticket", "s6rev": "Revision plan", "s6q": "Question"}, "questions": {"Q1": "True or false?", "Q2": "Complete the equation: glucose + ___ → ___ + ___", "Q3": "Explain why respiration is described as a \"controlled\" release of energy.", "Q4": "Germinating peas in a flask rise from 20 °C to 26 °C; boiled peas stay at 20 °C. Explain the results and the purpose of the boiled peas.", "Q5": "Explain why your breathing rate and heart rate increase when you run.", "Q6": "Plan an investigation to find whether temperature affects the rate of respiration of yeast. Name the variables and how you will measure the rate."}}'::jsonb, now()) on conflict (lesson) do update set title = excluded.title, spec = excluded.spec, updated_at = now();
insert into public.quizzes (id, topic_id, title, instructions, time_limit_minutes, max_attempts, published, show_results, category, feedback_mode, created_by) values ('20c5fa0f-e9f7-5399-b8c1-08f1972f98f4', '18ac6b04-8c8a-5bcd-895c-8f9f55db37df', 'Stage 8 Biology · Unit 4 Aerobic respiration · Checkpoint-style questions', 'Checkpoint-style questions for Stage 8 Biology, Unit 4 Aerobic respiration (objectives 8Bp.04, 8Bp.05), written in the style of the Cambridge Lower Secondary Checkpoint papers. 9 marks. Do the lesson first. Written answers are marked against the mark scheme and you get detailed feedback; your teacher checks every mark.', null, 2, true, true, 'quiz', 'hybrid', 'a9774d11-5d83-4bae-8da1-a6fb81c7dd7e') on conflict (id) do update set title = excluded.title, instructions = excluded.instructions, topic_id = excluded.topic_id;
