insert into public.lessons (id, topic_id, title, summary, url, external_id, max_marks, minutes, sort_order) values ('51c846e7-91c5-5a71-8d65-22213be67de2', 'c08b7880-aa06-5b4e-8f2a-9ac1c2769c07', 'Unit 5 Ecosystems, bioaccumulation and invasive species: Ecosystems under pressure', 'Stage 8 Biology · Objectives 8Be.01, 8Be.02, 8Be.03', '/cks8-bio-5/', 'CKS8-BIO-L5', 19, 60, 50) on conflict (external_id) do update set title = excluded.title, summary = excluded.summary, url = excluded.url, max_marks = excluded.max_marks, minutes = excluded.minutes, topic_id = excluded.topic_id, sort_order = excluded.sort_order;
insert into public.lesson_specs (lesson, title, spec, updated_at) values ('CKS8-BIO-L5', 'Unit 5 Ecosystems, bioaccumulation and invasive species: Ecosystems under pressure', '{"marks": {"1": [{"kind": "choice", "id": "q1_0", "q": "Q1", "max": 4, "n": 4, "ans": ["Ecosystem", "Habitat", "Ecosystem", "Habitat"], "tip": "Whole system or one place?"}], "2": [{"kind": "choice", "id": "q2_0", "q": "Q2", "max": 4, "n": 4, "ans": ["Producer", "Primary consumer", "Secondary consumer", "Top predator"], "tip": "Count the links."}, {"kind": "text", "id": "q2_1", "q": "Q3", "max": 2, "pts": [["increase", "more"], ["fewer predators", "not eaten", "less eaten"]], "tips": ["Who eats frogs?"]}], "3": [{"kind": "text", "id": "q3_0", "q": "Q4", "max": 3, "pts": [["increase", "higher", "more"], ["eat many", "eats lots", "many", "build up"], ["not broken down", "not excreted", "stored", "fat"]], "tips": ["Look along the chain."]}], "4": [{"kind": "text", "id": "q4_0", "q": "Q5", "max": 3, "pts": [["light", "block"], ["photosynth", "plants die", "oxygen"], ["fish", "decompos", "suffocat", "die"]], "tips": ["Light → plants → oxygen."]}], "5": [{"kind": "text", "id": "q5_0", "q": "Q6", "max": 3, "pts": [["no chemical", "no pesticide", "natural", "cheap", "pest"], ["spread", "no predator", "invasive", "multiply"], ["eat", "poison", "native", "other species", "compete"]], "tips": ["For and against."]}]}, "models": {"1": [["Q1", "The whole system with its living and non-living parts is an ecosystem; a particular place an organism lives is a habitat."]], "2": [["Q2", "Grass: producer; grasshopper: primary; frog: secondary; eagle: top predator."], ["Q3", "The frog population would increase [1] because fewer frogs are eaten by snakes [1]."]], "3": [["Q4", "The DDT concentration increases at each step, reaching 25 ppm in the osprey [1]; each animal eats many of the organisms below it [1], and DDT is not broken down or excreted, so it builds up in the body [1]."]], "4": [["Q5", "The hyacinth blocks light from reaching the water [1], so water plants cannot photosynthesise and die, producing less oxygen [1]; when they decompose bacteria use up more oxygen, so fish suffocate and die [1]."]], "5": [["Q6", "Advantage: it avoids chemical pesticides that could bioaccumulate [1]; risks: the new species may spread with no natural predators [1] and harm native species by eating, poisoning or out-competing them [1]."]], "6": [["Exit ticket", "The build-up of a toxin that is not broken down, increasing in concentration along a food chain."]]}, "labels": {"q2_1": "Q3", "q3_0": "Q4", "q4_0": "Q5", "q5_0": "Q6", "q6_0": "Exit ticket", "s6rev": "Revision plan", "s6q": "Question"}, "questions": {"Q1": "Ecosystem or habitat?", "Q2": "Grass → grasshopper → frog → snake → eagle. Name the…", "Q3": "In the food chain above, suggest what would happen to the frogs if the snakes died out, and explain.", "Q4": "DDT in water: 0.00005 ppm; plankton 0.04 ppm; small fish 0.5 ppm; large fish 2 ppm; osprey 25 ppm. Describe the pattern and explain it.", "Q5": "Explain how water hyacinth covering the surface of a lake can kill fish and water plants.", "Q6": "Cane toads were brought to Australia to eat beetles in sugar cane, but they spread and poisoned native predators. Use this example to give one advantage and two risks of biological control."}}'::jsonb, now()) on conflict (lesson) do update set title = excluded.title, spec = excluded.spec, updated_at = now();
