insert into public.lesson_specs (lesson, title, spec, updated_at) values ('CKS8-BIO-L6', 'Unit 6 Climate and weather (Earth and Space): Climate and weather: past and changing', '{"marks": {"1": [{"kind": "choice", "id": "q1_0", "q": "Q1", "max": 4, "n": 4, "ans": ["Weather", "Climate", "Weather", "Climate"], "tip": "Today, or the long-term average?"}], "2": [{"kind": "text", "id": "q2_0", "q": "Q2", "max": 2, "pts": [["ice", "colder", "glacier"], ["sea level", "lower"]], "tips": ["Ice and sea."]}], "3": [{"kind": "choice", "id": "q3_0", "q": "Q3", "max": 4, "n": 4, "ans": ["Increases", "Decreases", "Increases", "Increases"], "tip": "Adds CO₂/methane or removes CO₂?"}, {"kind": "text", "id": "q3_1", "q": "Q4", "max": 3, "pts": [["greenhouse", "absorb", "trap"], ["infrared", "heat", "energy"], ["warm", "temperature rise", "increase"]], "tips": ["Absorb → trap → warm."]}], "4": [{"kind": "text", "id": "q4_0", "q": "Q5", "max": 3, "pts": [["higher", "highest", "never", "more than"], ["human", "fossil fuel", "burning"], ["temperature", "warm", "together", "climate"]], "tips": ["Compare, cause, consequence."]}], "5": [{"kind": "text", "id": "q5_0", "q": "Q6", "max": 2, "pts": [["weather", "one week", "short"], ["climate", "average", "long", "years"]], "tips": ["Short term vs long term."]}]}, "models": {"1": [["Q1", "Short term: weather; long-term average: climate."]], "2": [["Q2", "It was much colder, with large ice sheets covering northern continents [1]; so much water was frozen that sea level was about 120 m lower [1]."]], "3": [["Q3", "Burning fuels, cattle and deforestation increase greenhouse gases; planting trees removes CO₂."], ["Q4", "Carbon dioxide is a greenhouse gas that absorbs [1] infrared radiation (heat) given off by the Earth [1]; more of it traps more energy, so the average global temperature rises [1]."]], "4": [["Q5", "Today''s level is far higher than at any time in 800 000 years [1]; it has risen because of human activities such as burning fossil fuels [1]; because CO₂ and temperature have always risen together, it suggests strong warming [1]."]], "5": [["Q6", "A cold week is weather, a short-term event [1]; climate change is about the long-term average over decades, which is rising even if some weeks are cold [1]."]], "6": [["Exit ticket", "Weather is day-to-day conditions; climate is the average weather over a long time."]]}, "labels": {"q2_0": "Q2", "q3_1": "Q4", "q4_0": "Q5", "q5_0": "Q6", "q6_0": "Exit ticket", "s6rev": "Revision plan", "s6q": "Question"}, "questions": {"Q1": "Weather or climate?", "Q2": "Describe what the Earth was like during the last ice age compared with today.", "Q3": "Does it increase greenhouse gases in the atmosphere?", "Q4": "Explain how an increase in carbon dioxide in the atmosphere can change the climate.", "Q5": "Ice cores show carbon dioxide between 180 and 300 ppm for 800 000 years; today it is 420 ppm. What does this suggest, and why do scientists find it worrying?", "Q6": "A friend says: \"We had a very cold week, so climate change is not happening.\" Use the difference between weather and climate to reply."}}'::jsonb, now()) on conflict (lesson) do update set title = excluded.title, spec = excluded.spec, updated_at = now();
