insert into public.lesson_specs (lesson, title, spec, updated_at) values ('CKS8-CHEM-L1', 'Unit 1 Inside the atom: Rutherford and the nuclear atom', '{"marks": {"1": [{"kind": "choice", "id": "q1_0", "q": "Q1", "max": 4, "n": 4, "ans": ["Proton", "Neutron", "Electron", "Electron"], "tip": "Charge and position."}], "3": [{"kind": "choice", "id": "q3_0", "q": "Q3", "max": 3, "n": 3, "ans": ["Mostly empty space", "Positive centre that repels", "Tiny, dense nucleus with most of the mass"], "tip": "Observation → conclusion."}, {"kind": "text", "id": "q3_1", "q": "Q4", "max": 3, "pts": [["through", "empty space"], ["bounce", "deflect", "back"], ["nucleus", "concentrated", "dense", "centre"]], "tips": ["Two observations, one conclusion."]}], "4": [{"kind": "text", "id": "q4_0", "q": "Q5", "max": 2, "pts": [["attract", "attraction", "electrostatic"], ["positive+negative", "opposite"]], "tips": ["Opposite charges."]}], "5": [{"kind": "text", "id": "q5_0", "q": "Q6", "max": 2, "pts": [["evidence", "experiment", "result"], ["fit", "explain", "change", "new model", "improve"]], "tips": ["Evidence vs model."]}]}, "models": {"1": [["Q1", "Proton +1 nucleus; neutron 0 nucleus; electron −1 outside, tiny mass."]], "2": [["Q2", "They should all pass through with little or no deflection, because the positive charge is spread thinly."]], "3": [["Q3", "Through: empty space; deflected: positive centre; bounced back: tiny dense nucleus."], ["Q4", "Most particles passed through, showing the atom is mostly empty space [1]; some were deflected or bounced back [1], showing the positive charge is concentrated in a tiny dense nucleus, not spread out [1]."]], "4": [["Q5", "The electrostatic attraction [1] between the positive nucleus and the negative electrons, because opposite charges attract [1]."]], "5": [["Q6", "New experimental evidence, such as the gold foil results [1], could not be explained by the old plum pudding model, so the model was changed to the nuclear model [1]."]], "6": [["Exit ticket", "Proton +1, neutron 0, electron −1."]]}, "labels": {"q2_0": "Q2", "q3_1": "Q4", "q4_0": "Q5", "q5_0": "Q6", "q6_0": "Exit ticket", "s6rev": "Revision plan", "s6q": "Question"}, "questions": {"Q1": "Which particle?", "Q2": "Predict what Thomson''s model says should happen to alpha particles fired at gold foil.", "Q3": "What does each observation show?", "Q4": "Explain why the gold foil results showed that the plum pudding model was wrong.", "Q5": "Explain what keeps the electrons in an atom.", "Q6": "Use the story of the atom to explain why scientific models can change."}}'::jsonb, now()) on conflict (lesson) do update set title = excluded.title, spec = excluded.spec, updated_at = now();
