insert into public.lesson_specs (lesson, title, spec, updated_at) values ('CKS8-CHEM-L2', 'Unit 2 Purity, concentration and chromatography: Purity, concentration and chromatography', '{"marks": {"1": [{"kind": "choice", "id": "q1_0", "q": "Q1", "max": 4, "n": 4, "ans": ["Pure", "Mixture", "Pure", "Mixture"], "tip": "One chemical or many?"}], "2": [{"kind": "choice", "id": "q2_0", "q": "Q2", "max": 3, "n": 3, "ans": ["More concentrated", "More dilute", "More concentrated"], "tip": "Particles per volume."}, {"kind": "text", "id": "q2_1", "q": "Q3", "max": 2, "pts": [["b"], ["same", "smaller volume", "more particles", "closer"]], "tips": ["Same solute, different volume."]}], "3": [{"kind": "choice", "id": "q3_0", "q": "Q4", "max": 3, "n": 3, "ans": ["So the ink does not run", "So the samples do not dissolve into the solvent", "Shows how far the solvent moved"], "tip": "Each step has a reason."}, {"kind": "text", "id": "q3_1", "q": "Q5", "max": 2, "pts": [["mixture", "three"], ["contains r", "red dye", "r is in", "contains red"]], "tips": ["Spots = substances."]}], "4": [{"kind": "text", "id": "q4_0", "q": "Q6", "max": 2, "pts": [["4.2 ÷ 7", "4.2/7", "4.2 / 7"], ["0.6"]], "tips": ["Substance ÷ solvent."]}], "5": [{"kind": "text", "id": "q5_0", "q": "Q7", "max": 3, "pts": [["spot", "baseline", "sample"], ["solvent", "run", "paper"], ["compare", "match", "same pattern", "rf"]], "tips": ["Sample, run, compare."]}]}, "models": {"1": [["Q1", "Distilled water and oxygen are single substances; juice and sea water are mixtures."]], "2": [["Q2", "More solute or less solvent: more concentrated; more solvent: more dilute."], ["Q3", "Solution B is more concentrated [1] because the same number of salt particles is in a smaller volume [1]."]], "3": [["Q4", "Pencil does not dissolve; samples must not wash into the solvent; the solvent front is needed for Rf."], ["Q5", "The black ink is a mixture of three dyes [1], one of which is dye R [1]."]], "4": [["Q6", "Rf = 4.2 ÷ 7.0 [1] = 0.6 [1]."]], "5": [["Q7", "Put spots of ink from the note and from each pen on a pencil baseline [1]; stand the paper in the same solvent and let it run [1]; the pen whose spots match the note''s spots (same pattern and Rf values) was used [1]."]], "6": [["Exit ticket", "One."]]}, "labels": {"q2_1": "Q3", "q3_1": "Q5", "q4_0": "Q6", "q5_0": "Q7", "q6_0": "Exit ticket", "s6rev": "Revision plan", "s6q": "Question"}, "questions": {"Q1": "Pure substance or mixture (chemically)?", "Q2": "More or less concentrated?", "Q3": "Solution A has 20 g of salt in 500 cm³; solution B has 20 g in 250 cm³. Which is more concentrated? Explain using particles.", "Q4": "Why is each step done?", "Q5": "A black ink gives three spots. One matches the spot from red dye R. What can you conclude?", "Q6": "A dye moves 4.2 cm and the solvent front moves 7.0 cm. Calculate the Rf value.", "Q7": "A forged note was written in blue ink. Describe how chromatography could show which of three suspects'' pens was used."}}'::jsonb, now()) on conflict (lesson) do update set title = excluded.title, spec = excluded.spec, updated_at = now();
