insert into public.lesson_specs (lesson, title, spec, updated_at) values ('CKS8-CHEM-L3', 'Unit 3 Word equations and energy changes: Word equations and energy changes', '{"marks": {"1": [{"kind": "choice", "id": "q1_0", "q": "Q1", "max": 4, "n": 4, "ans": ["magnesium oxide", "sodium chloride", "carbon dioxide", "copper oxide"], "tip": "Metal first, then -ide."}, {"kind": "text", "id": "q1_1", "q": "Q2", "max": 2, "pts": [["zinc+sulfuric acid"], ["zinc sulfate+hydrogen"]], "tips": ["Left → right."]}], "2": [{"kind": "text", "id": "q2_0", "q": "Q3", "max": 2, "pts": [["8"], ["exothermic"]], "tips": ["Rise → ?"]}], "3": [{"kind": "choice", "id": "q3_0", "q": "Q4", "max": 5, "n": 5, "ans": ["Exothermic", "Endothermic", "Exothermic", "Endothermic", "Exothermic"], "tip": "Hotter or colder surroundings?"}], "4": [{"kind": "text", "id": "q4_0", "q": "Q5", "max": 2, "pts": [["insulat", "reduce", "less"], ["energy", "heat", "loss", "surroundings"]], "tips": ["Where does energy escape?"]}], "5": [{"kind": "text", "id": "q5_0", "q": "Q6", "max": 3, "pts": [["endothermic"], ["insulat", "polystyrene", "cover"], ["amount", "more", "slow", "sealed", "safe", "non-toxic"]], "tips": ["Cold → take energy in."]}]}, "models": {"1": [["Q1", "Magnesium oxide; sodium chloride; carbon dioxide; copper oxide."], ["Q2", "zinc + sulfuric acid (reactants) [1] → zinc sulfate + hydrogen (products) [1]."]], "2": [["Q3", "The temperature rises by 8 °C [1]; it is exothermic [1]."]], "3": [["Q4", "Rise: exothermic (burning, freezing). Fall: endothermic (cold pack, photosynthesis)."]], "4": [["Q5", "Polystyrene is an insulator and the lid stops escape from the top [1], so less energy is lost to (or gained from) the surroundings and the reading is more accurate [1]."]], "5": [["Q6", "An endothermic change, which takes energy from the drink [1]; the pack should be insulated on the outside so it does not absorb energy from the air [1] and contain enough of the chemicals, sealed safely, to last an hour [1]."]], "6": [["Exit ticket", "It falls."]]}, "labels": {"q1_1": "Q2", "q2_0": "Q3", "q4_0": "Q5", "q5_0": "Q6", "q6_0": "Exit ticket", "s6rev": "Revision plan", "s6q": "Question"}, "questions": {"Q1": "Name the product.", "Q2": "Write a word equation for zinc reacting with sulfuric acid to make zinc sulfate and hydrogen. Label the reactants and products.", "Q3": "A student adds sodium hydroxide solution to hydrochloric acid. The temperature rises from 21 °C to 29 °C. Calculate the change and name the type of reaction.", "Q4": "Exothermic or endothermic?", "Q5": "Explain why a polystyrene cup with a lid is used when measuring temperature changes.", "Q6": "A company wants a pack that keeps a picnic drink cold for an hour. Suggest which type of change it should use, and two features of a good design."}}'::jsonb, now()) on conflict (lesson) do update set title = excluded.title, spec = excluded.spec, updated_at = now();
