insert into public.lessons (id, topic_id, title, summary, url, external_id, max_marks, minutes, sort_order) values ('8c604c8a-5a3f-50fd-855e-3da1dc515337', '8d784e49-c0fc-5bbd-843c-c4707fbee52d', 'Unit 4 Reactivity of metals: How metals react: the reactivity series', 'Stage 8 Chemistry · Objectives 8Cc.03, 8Cc.06', '/cks8-chem-4/', 'CKS8-CHEM-L4', 17, 60, 40) on conflict (external_id) do update set title = excluded.title, summary = excluded.summary, url = excluded.url, max_marks = excluded.max_marks, minutes = excluded.minutes, topic_id = excluded.topic_id, sort_order = excluded.sort_order;
insert into public.lesson_specs (lesson, title, spec, updated_at) values ('CKS8-CHEM-L4', 'Unit 4 Reactivity of metals: How metals react: the reactivity series', '{"marks": {"1": [{"kind": "choice", "id": "q1_0", "q": "Q1", "max": 3, "n": 3, "ans": ["Burns brightly", "Reacts slowly (corrodes)", "Does not react"], "tip": "Fast, slow or never."}], "2": [{"kind": "text", "id": "q2_0", "q": "Q2", "max": 3, "pts": [["sodium hydroxide"], ["hydrogen"], ["squeaky pop", "pop"]], "tips": ["Hydroxide + gas; test."]}], "3": [{"kind": "choice", "id": "q3_0", "q": "Q3", "max": 4, "n": 4, "ans": ["Most reactive", "2nd", "3rd", "Least reactive"], "tip": "More fizz = more reactive."}, {"kind": "text", "id": "q3_1", "q": "Q4", "max": 2, "pts": [["same+acid", "concentration", "volume"], ["same+mass", "size", "surface", "temperature"]], "tips": ["What must be the same?"]}], "4": [{"kind": "text", "id": "q4_0", "q": "Q5", "max": 2, "pts": [["unreactive", "inert", "not react"], ["corrode", "tarnish", "shiny", "last", "oxygen", "water"]], "tips": ["What does inert mean in use?"]}], "5": [{"kind": "text", "id": "q5_0", "q": "Q6", "max": 3, "pts": [["above zinc", "between calcium and zinc", "below calcium", "below sodium", "high"], ["hydrogen"], ["magnesium", "calcium"]], "tips": ["Water slowly, acid fast."]}]}, "models": {"1": [["Q1", "Magnesium burns; iron rusts slowly; gold is inert."]], "2": [["Q2", "sodium + water → sodium hydroxide [1] + hydrogen [1]; hydrogen gives a squeaky pop with a lighted splint [1]."]], "3": [["Q3", "Magnesium > zinc > iron > copper."], ["Q4", "Use the same volume and concentration of acid [1] and the same mass and size of each metal (at the same temperature) [1]."]], "4": [["Q5", "Gold is inert (very unreactive) [1], so it does not corrode or tarnish in air and water and stays shiny and conducts reliably [1]."]], "5": [["Q6", "M is fairly high in the series, below calcium but above zinc [1]; the gas is hydrogen [1]; M could be magnesium [1]."]], "6": [["Exit ticket", "Hydrogen."]]}, "labels": {"q2_0": "Q2", "q3_1": "Q4", "q4_0": "Q5", "q5_0": "Q6", "q6_0": "Exit ticket", "s6rev": "Revision plan", "s6q": "Question"}, "questions": {"Q1": "How does the metal react with oxygen?", "Q2": "Write the word equation for sodium reacting with water and describe the test for the gas produced.", "Q3": "Results with dilute acid. Place in order of reactivity.", "Q4": "Explain two ways to make this comparison a fair test.", "Q5": "Explain why gold is used for jewellery and electrical connectors in phones.", "Q6": "Metal M reacts slowly with cold water but quickly with dilute acid, giving bubbles that pop. Predict where M is in the reactivity series, name the gas and suggest which metal M could be."}}'::jsonb, now()) on conflict (lesson) do update set title = excluded.title, spec = excluded.spec, updated_at = now();
