insert into public.lesson_specs (lesson, title, spec, updated_at) values ('CKS8-CHEM-L5', 'Unit 5 Impure products and solubility of salts: Impure products and the solubility of salts', '{"marks": {"1": [{"kind": "choice", "id": "q1_0", "q": "Q1", "max": 3, "n": 3, "ans": ["Wanted product", "Unreacted reactant", "Solvent"], "tip": "What did we want?"}], "2": [{"kind": "text", "id": "q2_0", "q": "Q2", "max": 2, "pts": [["increase", "more"], ["110", "32", "78", "numbers"]], "tips": ["Use the numbers."]}], "3": [{"kind": "text", "id": "q3_0", "q": "Q3", "max": 2, "pts": [["110 − 32", "110 - 32"], ["78"]], "tips": ["Hot − cold."]}, {"kind": "choice", "id": "q3_1", "q": "Q4", "max": 2, "n": 2, "ans": ["Saturated", "Not saturated"], "tip": "Can more dissolve?"}], "4": [{"kind": "text", "id": "q4_0", "q": "Q5", "max": 2, "pts": [["solubility", "less soluble", "dissolves less"], ["cannot", "comes out", "too much", "excess"]], "tips": ["Solubility falls."]}], "5": [{"kind": "text", "id": "q5_0", "q": "Q6", "max": 4, "pts": [["dissolve", "hot water"], ["filter", "sand"], ["cool", "evaporat", "crystal"], ["filter", "wash", "dry"]], "tips": ["Dissolve, filter, crystallise, dry."]}]}, "models": {"1": [["Q1", "Copper sulfate is the product; leftover copper oxide is unreacted; water is the solvent."]], "2": [["Q2", "Solubility increases as temperature increases [1], from 32 g at 20 °C to 110 g per 100 g water at 60 °C [1]."]], "3": [["Q3", "110 − 32 [1] = 78 g of crystals [1]."], ["Q4", "If no more dissolves it is saturated."]], "4": [["Q5", "As the solution cools, the solubility of the salt decreases [1], so the extra solute can no longer stay dissolved and comes out as crystals [1]."]], "5": [["Q6", "Dissolve the mixture in hot water [1]; filter to remove the sand [1]; evaporate some water and cool so salt crystals form, leaving most of the impurity dissolved [1]; filter off the crystals, rinse with a little cold water and dry them [1]."]], "6": [["Exit ticket", "It increases."]]}, "labels": {"q2_0": "Q2", "q3_0": "Q3", "q4_0": "Q5", "q5_0": "Q6", "q6_0": "Exit ticket", "s6rev": "Revision plan", "s6q": "Question"}, "questions": {"Q1": "In the mixture after making a salt, what is each?", "Q2": "The solubility of potassium nitrate is 32 g/100 g water at 20 °C and 110 g/100 g water at 60 °C. Describe the effect of temperature.", "Q3": "A saturated solution of potassium nitrate in 100 g of water is cooled from 60 °C (110 g) to 20 °C (32 g). Calculate the mass of crystals formed.", "Q4": "Saturated or not?", "Q5": "Explain why cooling a hot saturated solution produces crystals.", "Q6": "A sample of salt is mixed with sand and a small amount of a coloured soluble impurity. Describe how to get pure salt crystals."}}'::jsonb, now()) on conflict (lesson) do update set title = excluded.title, spec = excluded.spec, updated_at = now();
