insert into public.lesson_specs (lesson, title, spec, updated_at) values ('CKS8-CHEM-L6', 'Unit 6 Earth''s resources (Earth and Space): Earth''s resources: renewable and non-renewable', '{"marks": {"1": [{"kind": "choice", "id": "q1_0", "q": "Q1", "max": 6, "n": 6, "ans": ["Non-renewable", "Renewable", "Non-renewable", "Renewable", "Non-renewable", "Renewable"], "tip": "Can it be replaced in a human lifetime?"}], "2": [{"kind": "text", "id": "q2_0", "q": "Q2", "max": 2, "pts": [["millions of years", "very long time", "slowly"], ["used", "faster", "run out", "cannot be replaced"]], "tips": ["Formation vs use."]}], "3": [{"kind": "choice", "id": "q3_0", "q": "Q3", "max": 4, "n": 4, "ans": ["Coal", "Wind", "Hydroelectric", "Geothermal"], "tip": "Each has a weakness."}, {"kind": "text", "id": "q3_1", "q": "Q4", "max": 2, "pts": [["renewable", "no carbon", "no pollution", "free", "no fuel"], ["night", "cloud", "weather", "space", "expensive"]], "tips": ["For and against."]}], "4": [{"kind": "text", "id": "q4_0", "q": "Q5", "max": 2, "pts": [["energy", "less energy", "95"], ["ore", "mining", "landfill", "waste", "resource", "conserve"]], "tips": ["Energy and resources."]}], "5": [{"kind": "text", "id": "q5_0", "q": "Q6", "max": 3, "pts": [["solar", "hydro", "river", "mini-hydro"], ["sunny", "river", "renewable", "no fuel", "free"], ["night", "battery", "dry season", "store", "cost", "both"]], "tips": ["Choose, justify, solve."]}]}, "models": {"1": [["Q1", "Coal, ore and gas are non-renewable; wind, geothermal and sunlight are renewable."]], "2": [["Q2", "They took millions of years to form [1] and are being used much faster than they can form, so they will run out [1]."]], "3": [["Q3", "Coal: CO₂; wind: still days; hydro: flooding; geothermal: location."], ["Q4", "Advantage: it is renewable and produces no carbon dioxide while working [1]; disadvantage: it does not work at night and less on cloudy days [1]."]], "4": [["Q5", "It uses much less energy (about 95% less) than extracting new aluminium [1]; it conserves the ore and reduces mining and landfill waste [1]."]], "5": [["Q6", "Solar panels (or a small hydroelectric generator) [1], because there is plenty of sunshine (or flowing water) and no fuel is needed [1]; solar does not work at night, so batteries are needed to store energy (or use both together) [1]."]], "6": [["Exit ticket", "Any two: geothermal, hydroelectric, wind, solar."]]}, "labels": {"q2_0": "Q2", "q3_1": "Q4", "q4_0": "Q5", "q5_0": "Q6", "q6_0": "Exit ticket", "s6rev": "Revision plan", "s6q": "Question"}, "questions": {"Q1": "Renewable or non-renewable?", "Q2": "Explain why fossil fuels are described as non-renewable.", "Q3": "Match the disadvantage to the resource.", "Q4": "Give one advantage and one disadvantage of solar power.", "Q5": "Explain two benefits of recycling aluminium cans.", "Q6": "A village far from the national grid needs electricity. It is sunny all year and has a fast river. Recommend an energy resource and justify your choice, including one problem and how to solve it."}}'::jsonb, now()) on conflict (lesson) do update set title = excluded.title, spec = excluded.spec, updated_at = now();
