insert into public.lesson_specs (lesson, title, spec, updated_at) values ('CKS8-PHYS-L1', 'Unit 1 Speed and distance/time graphs: Speed and distance–time graphs', '{"marks": {"1": [{"kind": "choice", "id": "q1_0", "q": "Q1", "max": 4, "n": 4, "ans": ["5 m/s", "20 m/s", "60 km/h", "1.5 m/s"], "tip": "Distance ÷ time."}], "2": [{"kind": "text", "id": "q2_0", "q": "Q2", "max": 2, "pts": [["50 × 3", "50x3"], ["150"]], "tips": ["d = s × t."]}, {"kind": "text", "id": "q2_1", "q": "Q3", "max": 2, "pts": [["24 ÷ 8", "24/8"], ["3"]], "tips": ["t = d ÷ s."]}], "3": [{"kind": "choice", "id": "q3_0", "q": "Q4", "max": 4, "n": 4, "ans": ["Stationary", "Constant speed", "Faster constant speed", "Speeding up"], "tip": "Flat, straight or curved?"}, {"kind": "text", "id": "q3_1", "q": "Q5", "max": 2, "pts": [["200 ÷ 40", "200/40"], ["5"]], "tips": ["Gradient."]}], "4": [{"kind": "text", "id": "q4_0", "q": "Q6", "max": 3, "pts": [["1200", "20 min"], ["60"], ["stop", "slower", "stationary", "includes"]], "tips": ["Total ÷ total."]}], "5": [{"kind": "text", "id": "q5_0", "q": "Q7", "max": 4, "pts": [["tape", "metre rule", "ruler", "distance"], ["stopwatch", "timer", "light gate", "time"], ["divide", "distance ÷ time", "speed ="], ["repeat", "mean", "light gate", "video"]], "tips": ["Distance, time, calculate, improve."]}]}, "models": {"1": [["Q1", "100÷20 = 5; 400÷20 = 20; 180÷3 = 60; 90÷60 = 1.5."]], "2": [["Q2", "50 × 3 [1] = 150 km [1]."], ["Q3", "24 ÷ 8 [1] = 3 hours [1]."]], "3": [["Q4", "Flat: stopped; straight: steady; steeper: faster; curve getting steeper: accelerating."], ["Q5", "200 ÷ 40 [1] = 5 m/s [1]."]], "4": [["Q6", "Total distance = 1200 m and total time = 20 min [1]; average speed = 60 m/min [1]; it is lower than the first part (120 m/min) because the stop and the slower last part are included [1]."]], "5": [["Q7", "Measure the distance travelled with a metre rule or tape [1]; time the run with a stopwatch (or light gates) [1]; speed = distance ÷ time [1]; repeat several times and take a mean, or use light gates to reduce reaction-time error [1]."]], "6": [["Exit ticket", "The object is stationary (not moving)."]]}, "labels": {"q2_0": "Q2", "q2_1": "Q3", "q3_1": "Q5", "q4_0": "Q6", "q5_0": "Q7", "q6_0": "Exit ticket", "s6rev": "Revision plan", "s6q": "Question"}, "questions": {"Q1": "Calculate the speed.", "Q2": "A bus travels at 50 km/h for 3 hours. How far does it go?", "Q3": "A cyclist travels 24 km at 8 km/h. How long does the journey take?", "Q4": "What does the line show?", "Q5": "On a distance–time graph, a line goes from (0 s, 0 m) to (40 s, 200 m). Calculate the speed.", "Q6": "A student walks 600 m in 5 minutes, stops for 5 minutes, then walks 600 m in 10 minutes. Calculate the average speed for the whole journey in m/min, and explain why it is lower than the speed of the first part.", "Q7": "Plan how to measure the average speed of a toy car rolling down a ramp. Give the equipment, the measurements and how to improve accuracy."}}'::jsonb, now()) on conflict (lesson) do update set title = excluded.title, spec = excluded.spec, updated_at = now();
