insert into public.lesson_specs (lesson, title, spec, updated_at) values ('CKS8-PHYS-L2', 'Unit 2 Forces, motion and moments: Forces, motion and turning effects', '{"marks": {"1": [{"kind": "choice", "id": "q1_0", "q": "Q1", "max": 4, "n": 4, "ans": ["200 N forwards", "0 N", "300 N backwards", "50 N up"], "tip": "Subtract opposite forces."}], "2": [{"kind": "text", "id": "q2_0", "q": "Q2", "max": 2, "pts": [["steady", "constant", "same speed"], ["balanced", "resultant is zero", "equal"]], "tips": ["Equal forces."]}], "3": [{"kind": "choice", "id": "q3_0", "q": "Q3", "max": 4, "n": 4, "ans": ["20 N m", "60 N m", "15 N m", "100 N m"], "tip": "F × d."}, {"kind": "text", "id": "q3_1", "q": "Q4", "max": 2, "pts": [["distance", "further", "longer"], ["moment", "turning", "less force", "smaller force"]], "tips": ["Moment = F × d."]}], "4": [{"kind": "text", "id": "q4_0", "q": "Q5", "max": 3, "pts": [["600 n m", "600", "400 × 1.5"], ["600 ÷ 600", "600/600", "÷ 600"], ["1 m", "1.0", "= 1"]], "tips": ["Clockwise = anticlockwise."]}], "5": [{"kind": "text", "id": "q5_0", "q": "Q6", "max": 3, "pts": [["50 ÷ 0.25", "50/0.25"], ["200"], ["longer", "distance", "less force", "smaller force"]], "tips": ["F = moment ÷ d."]}]}, "models": {"1": [["Q1", "200 N forwards; 0 N; 300 N backwards; 50 N up."]], "2": [["Q2", "She moves at a steady speed [1] because the forces are balanced (resultant force is zero) [1]."]], "3": [["Q3", "20; 60; 15; 100 N m."], ["Q4", "The handle is further from the pivot (hinge) [1], so the same force gives a bigger moment; a smaller force is needed to turn the door [1]."]], "4": [["Q5", "Child''s moment = 400 × 1.5 = 600 N m [1]; 600 × d = 600 so d = 600 ÷ 600 [1] = 1 m [1]."]], "5": [["Q6", "F = 50 ÷ 0.25 [1] = 200 N [1]; a longer spanner increases the distance, so a smaller force gives the same moment [1]."]], "6": [["Exit ticket", "Moment = force × perpendicular distance from the pivot."]]}, "labels": {"q2_0": "Q2", "q3_1": "Q4", "q4_0": "Q5", "q5_0": "Q6", "q6_0": "Exit ticket", "s6rev": "Revision plan", "s6q": "Question"}, "questions": {"Q1": "Calculate the resultant force.", "Q2": "A cyclist pedals with a force of 150 N and air resistance plus friction total 150 N. Describe and explain her motion.", "Q3": "Calculate the moment.", "Q4": "Explain why it is easier to open a door by pushing at the handle than near the hinge.", "Q5": "A 400 N child sits 1.5 m from the pivot of a see-saw. How far from the pivot must a 600 N adult sit on the other side to balance? Show your working.", "Q6": "A spanner 0.25 m long needs a moment of 50 N m to loosen a bolt. Calculate the force needed, and explain how a longer spanner would help."}}'::jsonb, now()) on conflict (lesson) do update set title = excluded.title, spec = excluded.spec, updated_at = now();
