insert into public.lessons (id, topic_id, title, summary, url, external_id, max_marks, minutes, sort_order) values ('6be575bc-3026-5a1b-ba75-3e127100040d', 'f8e5cbb5-a650-52c2-897b-5ca306577c92', 'Unit 3 Pressure and diffusion: Pressure and diffusion', 'Stage 8 Physics · Objectives 8Pf.05, 8Pf.06, 8Pf.07', '/cks8-phys-3/', 'CKS8-PHYS-L3', 24, 60, 30) on conflict (external_id) do update set title = excluded.title, summary = excluded.summary, url = excluded.url, max_marks = excluded.max_marks, minutes = excluded.minutes, topic_id = excluded.topic_id, sort_order = excluded.sort_order;
insert into public.lesson_specs (lesson, title, spec, updated_at) values ('CKS8-PHYS-L3', 'Unit 3 Pressure and diffusion: Pressure and diffusion', '{"marks": {"1": [{"kind": "choice", "id": "q1_0", "q": "Q1", "max": 4, "n": 4, "ans": ["10 N/cm²", "50 N/m²", "2 N/cm²", "4000 Pa"], "tip": "Force ÷ area."}, {"kind": "text", "id": "q1_1", "q": "Q2", "max": 2, "pts": [["large area", "wide feet", "big feet"], ["low pressure", "less pressure", "spread"]], "tips": ["Area and pressure."]}], "2": [{"kind": "choice", "id": "q2_0", "q": "Q3", "max": 4, "n": 4, "ans": ["Increases", "Increases", "Decreases", "Increases"], "tip": "More collisions?"}, {"kind": "text", "id": "q2_1", "q": "Q4", "max": 3, "pts": [["faster", "more energy", "move quickly"], ["collide", "collisions", "hit"], ["pressure", "force", "harder", "more often"]], "tips": ["Heat → speed → collisions."]}], "3": [{"kind": "text", "id": "q3_0", "q": "Q5", "max": 2, "pts": [["pressure", "greater"], ["depth", "deeper", "bottom", "weight of water"]], "tips": ["Pressure and depth."]}], "4": [{"kind": "text", "id": "q4_0", "q": "Q6", "max": 2, "pts": [["particles", "molecules"], ["random", "move", "spread", "high to low", "diffus"]], "tips": ["Particles move."]}, {"kind": "choice", "id": "q4_1", "q": "Q7", "max": 3, "n": 3, "ans": ["Faster", "Slower", "Faster"], "tip": "Speed of particles."}], "5": [{"kind": "text", "id": "q5_0", "q": "Q8", "max": 4, "pts": [["temperature"], ["time", "spread", "evenly"], ["volume", "same", "drops", "beaker"], ["repeat", "thermometer", "mean"]], "tips": ["Change, measure, control, repeat."]}]}, "models": {"1": [["Q1", "10; 50; 2 N/cm²; 4000 Pa."], ["Q2", "Its wide feet have a large area [1], so its weight is spread out and the pressure on the sand is low [1]."]], "2": [["Q3", "More particles, higher temperature or less volume: more collisions, higher pressure."], ["Q4", "Heating makes the gas particles move faster [1], so they collide with the walls more often and harder [1]; the pressure increases until the can bursts [1]."]], "3": [["Q5", "Water pressure is greater at the bottom [1] because it increases with depth (more water above pushing down) [1]."]], "4": [["Q6", "Smell particles from the food move randomly through the air [1] and spread from high to low concentration by diffusion until they reach your nose [1]."], ["Q7", "Gases and higher temperatures: faster."]], "5": [["Q8", "Change the water temperature, e.g. 10, 30, 50 °C [1]; measure the time for the colour to spread evenly through the water [1]; keep the volume of water, beaker size and number of drops the same, and do not stir [1]; check temperatures with a thermometer and repeat to get a mean [1]."]], "6": [["Exit ticket", "Pressure = force ÷ area."]]}, "labels": {"q1_1": "Q2", "q2_1": "Q4", "q3_0": "Q5", "q4_0": "Q6", "q5_0": "Q8", "q6_0": "Exit ticket", "s6rev": "Revision plan", "s6q": "Question"}, "questions": {"Q1": "Calculate the pressure.", "Q2": "Explain why a camel does not sink into soft sand.", "Q3": "Does the gas pressure increase or decrease?", "Q4": "Use particles to explain why a sealed can may burst if heated.", "Q5": "Explain why a dam is built much thicker at the bottom than at the top.", "Q6": "Explain why the smell of cooking spreads through a house.", "Q7": "Faster or slower diffusion?", "Q8": "Plan an investigation into how temperature affects how fast a drop of food colouring spreads in water. Include variables and how to measure."}}'::jsonb, now()) on conflict (lesson) do update set title = excluded.title, spec = excluded.spec, updated_at = now();
