insert into public.lesson_specs (lesson, title, spec, updated_at) values ('CKS8-PHYS-L4', 'Unit 4 Light: reflection, refraction and colour: Light: reflection, refraction and colour', '{"marks": {"1": [{"kind": "choice", "id": "q1_0", "q": "Q1", "max": 4, "n": 4, "ans": ["35°", "55°", "90°", "70°"], "tip": "Measure from the normal."}], "2": [{"kind": "choice", "id": "q2_0", "q": "Q2", "max": 4, "n": 4, "ans": ["Towards the normal", "Away from the normal", "No bending", "Away from the normal"], "tip": "Slower = towards."}, {"kind": "text", "id": "q2_1", "q": "Q3", "max": 2, "pts": [["refract", "bend"], ["speed", "water to air", "leaves the water", "changes direction"]], "tips": ["Light leaving the water."]}], "3": [{"kind": "text", "id": "q3_0", "q": "Q4", "max": 3, "pts": [["spectrum", "colours", "rainbow"], ["refract", "bend"], ["different amount", "different colours bend", "violet most", "red least"]], "tips": ["Split, why?"]}], "4": [{"kind": "choice", "id": "q4_0", "q": "Q5", "max": 4, "n": 4, "ans": ["Red", "Black", "White", "Yellow"], "tip": "What can be reflected?"}, {"kind": "text", "id": "q4_1", "q": "Q6", "max": 2, "pts": [["red filter+only red", "red light", "only red"], ["absorb", "no green", "reflects green", "cannot reflect"]], "tips": ["Which light reaches the leaf?"]}], "5": [{"kind": "text", "id": "q5_0", "q": "Q7", "max": 3, "pts": [["45", "angle"], ["reflect", "angle of incidence", "equals"], ["twice", "second mirror", "down", "eye", "90"]], "tips": ["Two reflections."]}]}, "models": {"1": [["Q1", "Reflection 35°; 90 − 35 = 55° to the mirror; the normal is at 90°; 35 + 35 = 70°."]], "2": [["Q2", "Into a denser material: towards; out of it: away; along the normal: straight on."], ["Q3", "Light from the part of the straw under water refracts (bends) as it passes from water into air [1] because it speeds up, so it appears to come from a different place [1]."]], "3": [["Q4", "White light is split into a spectrum of colours [1] because each colour is refracted [1] by a different amount (violet most, red least) [1]."]], "4": [["Q5", "Red in white light; black in blue (no red to reflect); white; yellow."], ["Q6", "The red filter lets only red light through [1]; the leaf reflects only green and absorbs red, so no light reaches your eye and it looks black [1]."]], "5": [["Q7", "Light from the object hits the top mirror at 45° [1]; it reflects at the same angle (angle of incidence = angle of reflection), turning through 90° down the tube [1]; the second mirror reflects it through 90° again into the soldier''s eye [1]."]], "6": [["Exit ticket", "The angle of incidence equals the angle of reflection."]]}, "labels": {"q2_1": "Q3", "q3_0": "Q4", "q4_1": "Q6", "q5_0": "Q7", "q6_0": "Exit ticket", "s6rev": "Revision plan", "s6q": "Question"}, "questions": {"Q1": "A ray hits a mirror at an angle of incidence of 35°. Find:", "Q2": "Towards or away from the normal?", "Q3": "Explain why a straw looks bent where it enters water.", "Q4": "Describe and explain what happens when white light passes through a prism.", "Q5": "What colour does it look?", "Q6": "Explain why a green leaf looks black when seen through a red filter.", "Q7": "Explain how two plane mirrors at 45° in a tube let a soldier see over a wall. Include the law of reflection."}}'::jsonb, now()) on conflict (lesson) do update set title = excluded.title, spec = excluded.spec, updated_at = now();
insert into public.quizzes (id, topic_id, title, instructions, time_limit_minutes, max_attempts, published, show_results, category, feedback_mode, created_by) values ('fb3f9373-4d4a-53c3-b02e-d503aededd60', '7f0a5712-4e4e-5ea1-a075-e3d9437d1261', 'Stage 8 Physics · Unit 4 Light: reflection, refraction and colour · Checkpoint-style questions', 'Checkpoint-style questions for Stage 8 Physics, Unit 4 Light: reflection, refraction and colour (objectives 8Ps.01, 8Ps.02, 8Ps.03, 8Ps.04), written in the style of the Cambridge Lower Secondary Checkpoint papers. 7 marks. Do the lesson first. Written answers are marked against the mark scheme and you get detailed feedback; your teacher checks every mark.', null, 2, true, true, 'quiz', 'hybrid', 'a9774d11-5d83-4bae-8da1-a6fb81c7dd7e') on conflict (id) do update set title = excluded.title, instructions = excluded.instructions, topic_id = excluded.topic_id;
