insert into public.lessons (id, topic_id, title, summary, url, external_id, max_marks, minutes, sort_order) values ('e70b1eff-f141-5721-a6d4-6544f61cf30e', '45e111dd-1543-5e85-a650-f6fe211d6ffb', 'Unit 5 Magnetism and electromagnets: Magnets, fields and electromagnets', 'Stage 8 Physics · Objectives 8Pe.01, 8Pe.02, 8Pe.03, 8ESp.01', '/cks8-phys-5/', 'CKS8-PHYS-L5', 18, 60, 50) on conflict (external_id) do update set title = excluded.title, summary = excluded.summary, url = excluded.url, max_marks = excluded.max_marks, minutes = excluded.minutes, topic_id = excluded.topic_id, sort_order = excluded.sort_order;
insert into public.lesson_specs (lesson, title, spec, updated_at) values ('CKS8-PHYS-L5', 'Unit 5 Magnetism and electromagnets: Magnets, fields and electromagnets', '{"marks": {"1": [{"kind": "choice", "id": "q1_0", "q": "Q1", "max": 5, "n": 5, "ans": ["Attract", "Repel", "Attract", "No force", "Repel"], "tip": "Like repel, unlike attract."}], "2": [{"kind": "text", "id": "q2_0", "q": "Q2", "max": 2, "pts": [["compass", "place", "around"], ["mark", "direction", "dots", "join", "arrow"]], "tips": ["Place, mark, join."]}, {"kind": "text", "id": "q2_1", "q": "Q3", "max": 2, "pts": [["earth", "magnetic field", "magnet"], ["core", "line up", "align", "attract"]], "tips": ["The Earth is a magnet."]}], "3": [{"kind": "text", "id": "q3_0", "q": "Q4", "max": 2, "pts": [["switch", "turn off", "on and off"], ["strength", "stronger", "change", "adjust", "control"]], "tips": ["Control."]}], "4": [{"kind": "text", "id": "q4_0", "q": "Q5", "max": 3, "pts": [["more turns", "increase", "proportional"], ["4 per 10", "doubl", "directly"], ["16"]], "tips": ["Spot the pattern."]}], "5": [{"kind": "text", "id": "q5_0", "q": "Q6", "max": 4, "pts": [["current", "ammeter", "variable resistor"], ["paper clips", "number of clips", "mass lifted"], ["turns", "same", "core", "wire"], ["hot", "switch off", "low", "burn"]], "tips": ["Change, measure, control, safety."]}]}, "models": {"1": [["Q1", "N–S attract; N–N and S–S repel; iron is attracted; copper is not magnetic."]], "2": [["Q2", "Place a plotting compass near the magnet and mark the direction its needle points [1]; move the compass along, marking dots, and join them into field lines with arrows from N to S [1]."], ["Q3", "The Earth acts like a giant magnet because of its iron core [1], so the compass needle (a small magnet) lines up with the Earth''s magnetic field [1]."]], "3": [["Q4", "It can be switched on and off [1]; its strength can be changed by changing the current [1]."]], "4": [["Q5", "As the number of turns increases, more clips are lifted [1]; the number of clips is proportional, 4 more for each extra 10 turns [1]; 40 turns should lift about 16 clips [1]."]], "5": [["Q6", "Change the current with a variable resistor, measuring it with an ammeter [1]; measure strength by the number of paper clips lifted [1]; keep the number of turns, the core and the type of clips the same [1]; switch off between readings because the wire can get hot [1]."]], "6": [["Exit ticket", "Any two: more turns, larger current, add an iron core."]]}, "labels": {"q2_0": "Q2", "q2_1": "Q3", "q3_0": "Q4", "q4_0": "Q5", "q5_0": "Q6", "q6_0": "Exit ticket", "s6rev": "Revision plan", "s6q": "Question"}, "questions": {"Q1": "Attract, repel or no force?", "Q2": "Describe how to use plotting compasses to show the field around a bar magnet.", "Q3": "Explain why a compass needle points north.", "Q4": "Give two advantages of an electromagnet over a permanent magnet.", "Q5": "A student records paper clips lifted: 10 turns, 4 clips; 20 turns, 8 clips; 30 turns, 12 clips. Describe the pattern and predict the number for 40 turns.", "Q6": "Plan an investigation into how the current affects the strength of an electromagnet. Name the variables, equipment and one safety point."}}'::jsonb, now()) on conflict (lesson) do update set title = excluded.title, spec = excluded.spec, updated_at = now();
