insert into public.lesson_specs (lesson, title, spec, updated_at) values ('CKS8-PHYS-L6', 'Unit 6 Galaxies and asteroids (Earth and Space): Galaxies and asteroids', '{"marks": {"1": [{"kind": "choice", "id": "q1_0", "q": "Q1", "max": 5, "n": 5, "ans": ["4th", "1st", "5th", "2nd", "3rd"], "tip": "Planet → star → system → galaxy → Universe."}], "2": [{"kind": "text", "id": "q2_0", "q": "Q2", "max": 2, "pts": [["inside", "within", "part of"], ["disc", "flat", "edge", "many stars"]], "tips": ["We are inside it."]}], "3": [{"kind": "choice", "id": "q3_0", "q": "Q3", "max": 3, "n": 3, "ans": ["Asteroid", "Comet", "Asteroid"], "tip": "Rock or ice?"}, {"kind": "text", "id": "q3_1", "q": "Q4", "max": 2, "pts": [["jupiter"], ["gravity", "pull", "disturb", "stopped"]], "tips": ["A giant neighbour."]}], "4": [{"kind": "text", "id": "q4_0", "q": "Q5", "max": 2, "pts": [["past", "ago", "old light", "left"], ["2.5 million", "not now", "as it was"]], "tips": ["When did the light leave?"]}], "5": [{"kind": "text", "id": "q5_0", "q": "Q6", "max": 3, "pts": [["collide", "hit", "impact", "danger"], ["damage", "extinction", "climate", "destroy"], ["miss", "change path", "push", "deflect"]], "tips": ["Risk and response."]}]}, "models": {"1": [["Q1", "Earth, Sun, Solar System, galaxy, Universe."]], "2": [["Q2", "We are inside the Milky Way, which is a flat disc [1], so looking along the disc we see the light of billions of distant stars as a band [1]."]], "3": [["Q3", "Rocky, in the belt: asteroid; icy with a tail: comet."], ["Q4", "Jupiter''s strong gravity [1] disturbed their orbits and stopped them clumping together into a planet [1]."]], "4": [["Q5", "The light we see left Andromeda 2.5 million years ago [1], so we see the galaxy as it was in the past, not as it is now [1]."]], "5": [["Q6", "A large asteroid could collide with Earth [1], causing great damage, climate change or extinctions [1]; changing its orbit early could push it onto a path that misses Earth [1]."]], "6": [["Exit ticket", "A huge system of stars, gas, dust and planetary systems held together by gravity."]]}, "labels": {"q2_0": "Q2", "q3_1": "Q4", "q4_0": "Q5", "q5_0": "Q6", "q6_0": "Exit ticket", "s6rev": "Revision plan", "s6q": "Question"}, "questions": {"Q1": "Put in order of size, smallest first.", "Q2": "Explain why the Milky Way appears as a band of light across the night sky.", "Q3": "Asteroid or comet?", "Q4": "Explain why the asteroids in the asteroid belt never formed a planet.", "Q5": "Light from the Andromeda galaxy takes 2.5 million years to reach us. Explain what this tells us about what we see when we look at it.", "Q6": "In 2022 NASA''s DART spacecraft crashed into a small asteroid and changed its orbit. Suggest why scientists track near-Earth asteroids and why changing an orbit could protect Earth."}}'::jsonb, now()) on conflict (lesson) do update set title = excluded.title, spec = excluded.spec, updated_at = now();
