insert into public.lesson_specs (lesson, title, spec, updated_at) values ('CKS8-MATHS-L1', 'Unit 1 Integers, powers and roots: Primes, powers and roots', '{"marks": {"1": [{"kind": "choice", "id": "q1_0", "q": "Q1", "max": 5, "n": 5, "ans": ["19", "5", "9", "−9", "28"], "tip": "BIDMAS."}], "2": [{"kind": "text", "id": "q2_0", "q": "Q2", "max": 2, "pts": [["2 × 2 × 2 × 3 × 3", "2x2x2x3x3", "factor tree", "2, 2, 2, 3, 3"], ["2³ × 3²", "2^3 × 3^2", "2^3x3^2", "2³×3²"]], "tips": ["Factor tree."]}, {"kind": "text", "id": "q2_1", "q": "Q3", "max": 2, "pts": [["6"], ["72"]], "tips": ["Shared primes / highest powers."]}], "3": [{"kind": "choice", "id": "q3_0", "q": "Q4", "max": 4, "n": 4, "ans": ["5⁷", "7⁵", "1", "2¹⁰"], "tip": "Add or subtract the indices."}], "4": [{"kind": "choice", "id": "q4_0", "q": "Q5", "max": 4, "n": 4, "ans": ["6 or −6", "−4", "−27", "0.5"], "tip": "Signs matter."}, {"kind": "text", "id": "q4_1", "q": "Q6", "max": 2, "pts": [["square+positive", "squared is positive", "two negatives", "never negative"], ["cube+negative", "three negatives", "cubed is negative"]], "tips": ["Think about signs."]}], "5": [{"kind": "text", "id": "q5_0", "q": "Q7", "max": 3, "pts": [["lcm", "2² × 3", "2 × 3²"], ["36"], ["8:36", "08:36"]], "tips": ["LCM."]}]}, "models": {"1": [["Q1", "19; 5; 9; −9; 28."]], "2": [["Q2", "72 = 2 × 2 × 2 × 3 × 3 [1] = 2³ × 3² [1]."], ["Q3", "18 = 2 × 3², 24 = 2³ × 3: HCF = 2 × 3 = 6 [1]; LCM = 2³ × 3² = 72 [1]."]], "3": [["Q4", "5⁷; 7⁵; 1; 2¹⁰."]], "4": [["Q5", "±6; −4; −27; 0.5."], ["Q6", "Any number squared is positive (or zero), so no real number squared gives a negative [1]; a negative number cubed is negative, so negative numbers do have cube roots [1]."]], "5": [["Q7", "This needs the LCM of 12 and 18 [1]; 12 = 2² × 3, 18 = 2 × 3², LCM = 36 [1]; they next leave together at 8:36 [1]."]], "6": [["Exit ticket", "3² × 5."]]}, "labels": {"q2_0": "Q2", "q2_1": "Q3", "q4_1": "Q6", "q5_0": "Q7", "q6_0": "Exit ticket", "s6rev": "Revision plan", "s6q": "Question"}, "questions": {"Q1": "Calculate.", "Q2": "Write 72 as a product of prime factors in index form.", "Q3": "Find the HCF and LCM of 18 and 24.", "Q4": "Simplify.", "Q5": "Find the value.", "Q6": "Explain why a negative number has no square root in the set of real numbers, but does have a cube root.", "Q7": "Buses leave a station every 12 minutes and trains every 18 minutes. Both leave at 8:00. When do they next leave together? Show your method."}}'::jsonb, now()) on conflict (lesson) do update set title = excluded.title, spec = excluded.spec, updated_at = now();
