insert into public.lesson_specs (lesson, title, spec, updated_at) values ('CKS8-MATHS-L2', 'Unit 2 Place value and rounding: Place value and significant figures', '{"marks": {"1": [{"kind": "choice", "id": "q1_0", "q": "Q1", "max": 5, "n": 5, "ans": ["4.5", "320", "0.07", "6000", "2.4"], "tip": "Smaller or bigger?"}], "2": [{"kind": "choice", "id": "q2_0", "q": "Q2", "max": 4, "n": 4, "ans": ["48 000 000", "0.035", "7000", "3.1"], "tip": "Start at the first non-zero digit."}], "3": [{"kind": "text", "id": "q3_0", "q": "Q3", "max": 2, "pts": [["6 × 40 ÷ 0.2", "6×40÷0.2", "240 ÷ 0.2", "240"], ["1200"]], "tips": ["Round, then calculate."]}], "4": [{"kind": "text", "id": "q4_0", "q": "Q4", "max": 2, "pts": [["33.33"], ["cent", "money", "2 decimal", "nearest"]], "tips": ["Money."]}], "5": [{"kind": "text", "id": "q5_0", "q": "Q5", "max": 3, "pts": [["0.5 × 200", "100"], ["wrong", "too big", "10 times"], ["98.4"]], "tips": ["Estimate first."]}]}, "models": {"1": [["Q1", "4.5; 320; 0.07; 6000; 2.4."]], "2": [["Q2", "48 000 000; 0.035; 7000; 3.1."]], "3": [["Q3", "6 × 40 ÷ 0.2 [1] = 240 ÷ 0.2 = 1200 [1]."]], "4": [["Q4", "$33.33 [1] because money is given to the nearest cent (2 decimal places) [1]."]], "5": [["Q5", "Estimate: 0.5 × 200 = 100 [1]; 984 is about ten times too big, so it is wrong [1]; the correct answer is 98.4 [1]."]], "6": [["Exit ticket", "0.0085."]]}, "labels": {"q3_0": "Q3", "q4_0": "Q4", "q5_0": "Q5", "q6_0": "Exit ticket", "s6rev": "Revision plan", "s6q": "Question"}, "questions": {"Q1": "Calculate.", "Q2": "Round to the stated number of significant figures.", "Q3": "Estimate 6.12 × 39.8 ÷ 0.198 by rounding each number to 1 significant figure.", "Q4": "Share $100 equally between 3 people. A calculator gives 33.333 333. Write a sensible answer and explain.", "Q5": "A student calculates 0.48 × 205 and gets 984. Use an estimate to show the answer is wrong and give the correct answer."}}'::jsonb, now()) on conflict (lesson) do update set title = excluded.title, spec = excluded.spec, updated_at = now();
