insert into public.lesson_specs (lesson, title, spec, updated_at) values ('CKS8-MATHS-L3', 'Unit 3 Fractions, decimals and percentages: Calculating with fractions, decimals and percentages', '{"marks": {"1": [{"kind": "choice", "id": "q1_0", "q": "Q1", "max": 4, "n": 4, "ans": ["0.333…", "0.125", "0.1818…", "0.8333…"], "tip": "Divide."}], "2": [{"kind": "choice", "id": "q2_0", "q": "Q2", "max": 4, "n": 4, "ans": ["2 7/12", "14", "8", "1 1/2"], "tip": "Improper fractions first."}, {"kind": "text", "id": "q2_1", "q": "Q3", "max": 2, "pts": [["6 ÷ 3/4", "× 4/3", "x 4/3", "24/3"], ["8"]], "tips": ["Divide by the fraction."]}], "3": [{"kind": "choice", "id": "q3_0", "q": "Q4", "max": 4, "n": 4, "ans": ["$34", "280", "25%", "20%"], "tip": "Change ÷ original."}, {"kind": "text", "id": "q3_1", "q": "Q5", "max": 2, "pts": [["1.08", "20"], ["270"]], "tips": ["Multiplier or add 8%."]}], "4": [{"kind": "choice", "id": "q4_0", "q": "Q6", "max": 4, "n": 4, "ans": ["0.042", "24", "1.44", "0.15"], "tip": "Decimal places; scale the divisor."}, {"kind": "text", "id": "q4_1", "q": "Q7", "max": 2, "pts": [["−1/2", "-1/2", "−0.5"], ["−0.45, 3/8, 0.4", "-0.45, 3/8, 0.4", "−0.45, 0.375, 0.4"]], "tips": ["Convert to decimals."]}], "5": [{"kind": "text", "id": "q5_0", "q": "Q8", "max": 3, "pts": [["45"], ["45", "0.9 × 50"], ["b", "$0", "same", "0"]], "tips": ["Calculate both."]}]}, "models": {"1": [["Q1", "1/3 = 0.333…; 1/8 = 0.125; 2/11 = 0.1818…; 5/6 = 0.8333…."]], "2": [["Q2", "2 7/12; 14; 8; 1 1/2."], ["Q3", "6 ÷ 3/4 = 6 × 4/3 [1] = 8 scoops [1]."]], "3": [["Q4", "$34; 280; 20/80 = 25%; 10/50 = 20%."], ["Q5", "8% of 250 = $20 (or 250 × 1.08) [1]; new price $270 [1]."]], "4": [["Q6", "0.042; 24; 1.44; 0.15."], ["Q7", "−1/2 (−0.5) [1], −0.45, 3/8 (0.375), 0.4 [1]."]], "5": [["Q8", "Shop A: 60 × 0.75 = $45 [1]; Shop B: 50 × 0.9 = $45 [1]; both cost $45, so neither is cheaper [1]."]], "6": [["Exit ticket", "$64."]]}, "labels": {"q2_1": "Q3", "q3_1": "Q5", "q4_1": "Q7", "q5_0": "Q8", "q6_0": "Exit ticket", "s6rev": "Revision plan", "s6q": "Question"}, "questions": {"Q1": "Match the fraction to its decimal.", "Q2": "Calculate.", "Q3": "How many 3/4-cup scoops make 6 cups? Show your working.", "Q4": "Calculate.", "Q5": "A phone costs $250. Its price increases by 8%. Calculate the new price.", "Q6": "Calculate.", "Q7": "Write these in order, smallest first: 0.4, −1/2, −0.45, 3/8.", "Q8": "Shop A sells a $60 bag with 25% off. Shop B sells the same bag for $50 with 10% off. Which is cheaper and by how much?"}}'::jsonb, now()) on conflict (lesson) do update set title = excluded.title, spec = excluded.spec, updated_at = now();
