insert into public.lesson_specs (lesson, title, spec, updated_at) values ('CKS8-MATHS-L4', 'Unit 4 Ratio and proportion: Ratio and direct proportion', '{"marks": {"1": [{"kind": "choice", "id": "q1_0", "q": "Q1", "max": 4, "n": 4, "ans": ["2 : 3", "1 : 4", "3 : 5", "1 : 20"], "tip": "Same units, then divide by the HCF."}], "2": [{"kind": "text", "id": "q2_0", "q": "Q2", "max": 2, "pts": [["9 parts", "8", "72 ÷ 9"], ["40, 24, 8", "40 24 8", "40, 24 and 8"]], "tips": ["Total parts."]}], "3": [{"kind": "text", "id": "q3_0", "q": "Q3", "max": 2, "pts": [["75"], ["2250", "2.25"]], "tips": ["One person first."]}, {"kind": "choice", "id": "q3_1", "q": "Q4", "max": 3, "n": 3, "ans": ["Direct proportion", "Not direct proportion", "Direct proportion"], "tip": "Does doubling one double the other?"}], "4": [{"kind": "text", "id": "q4_0", "q": "Q5", "max": 3, "pts": [["3/8", "0.375"], ["4/11", "0.364"], ["a"]], "tips": ["Fraction that is red."]}], "5": [{"kind": "text", "id": "q5_0", "q": "Q6", "max": 2, "pts": [["300 000", "300000"], ["3"]], "tips": ["Multiply, then convert."]}]}, "models": {"1": [["Q1", "2 : 3; 1 : 4; 300 : 500 = 3 : 5; 5 : 100 = 1 : 20."]], "2": [["Q2", "9 parts, one part = 8 [1]; 40, 24 and 8 [1]."]], "3": [["Q3", "300 ÷ 4 = 75 g per person [1]; 75 × 30 = 2250 g [1]."], ["Q4", "Pens–cost and petrol–cost are proportional; age–height is not."]], "4": [["Q5", "Paint A is 3/8 = 0.375 red [1]; Paint B is 4/11 ≈ 0.364 red [1]; so Paint A is redder [1]."]], "5": [["Q6", "6 × 50 000 = 300 000 cm [1] = 3 km [1]."]], "6": [["Exit ticket", "$30 and $20."]]}, "labels": {"q2_0": "Q2", "q3_0": "Q3", "q4_0": "Q5", "q5_0": "Q6", "q6_0": "Exit ticket", "s6rev": "Revision plan", "s6q": "Question"}, "questions": {"Q1": "Simplify.", "Q2": "Share 72 sweets in the ratio 5 : 3 : 1.", "Q3": "A recipe for 4 people uses 300 g of flour. How much flour is needed for 30 people?", "Q4": "Direct proportion or not?", "Q5": "Paint A mixes red and white in the ratio 3 : 5. Paint B mixes them 4 : 7. Which is redder? Show your working.", "Q6": "A map has a scale of 1 : 50 000. Two villages are 6 cm apart on the map. Find the real distance in kilometres."}}'::jsonb, now()) on conflict (lesson) do update set title = excluded.title, spec = excluded.spec, updated_at = now();
