insert into public.lesson_specs (lesson, title, spec, updated_at) values ('CKS8-MATHS-L5', 'Unit 5 Expressions, formulae and equations: Expressions, formulae and equations', '{"marks": {"1": [{"kind": "choice", "id": "q1_0", "q": "Q1", "max": 5, "n": 5, "ans": ["Expression", "Formula", "Equation", "Expression", "Formula"], "tip": "Equals sign? Linked variables?"}], "2": [{"kind": "choice", "id": "q2_0", "q": "Q2", "max": 4, "n": 4, "ans": ["8x − 12", "−3x − 15", "6(2x + 3)", "5x(x − 2)"], "tip": "Opposites."}], "3": [{"kind": "choice", "id": "q3_0", "q": "Q3", "max": 4, "n": 4, "ans": ["5", "7", "8", "−3"], "tip": "Same to both sides."}, {"kind": "text", "id": "q3_1", "q": "Q4", "max": 3, "pts": [["2(x + 7) + 2x", "4x + 14", "2x + 14 + 2x"], ["4x = 32", "= 46"], ["8"]], "tips": ["Perimeter = 2l + 2w."]}], "4": [{"kind": "text", "id": "q4_0", "q": "Q5", "max": 2, "pts": [["c − 5", "c - 5", "c-5"], ["/12", "÷ 12", "/ 12", "over 12", "÷12"]], "tips": ["Undo +5, then ×12."]}, {"kind": "choice", "id": "q4_1", "q": "Q6", "max": 3, "n": 3, "ans": ["2 < x ≤ 6", "−1 ≤ x < 4", "x > 3"], "tip": "At least/at most include the end."}], "5": [{"kind": "text", "id": "q5_0", "q": "Q7", "max": 3, "pts": [["3x + 4 = 2(x + 4)", "3x+4=2(x+4)", "3x + 4", "2(x + 4)"], ["x = 4", "x=4", "brother is 4", "brother 4"], ["12"]], "tips": ["Let the brother be x."]}]}, "models": {"1": [["Q1", "Expression; formula; equation; expression; formula."]], "2": [["Q2", "8x − 12; −3x − 15; 6(2x + 3); 5x(x − 2)."]], "3": [["Q3", "x = 5; 7; 8; −3."], ["Q4", "2(x + 7) + 2x = 46 [1]; 4x + 14 = 46 so 4x = 32 [1]; x = 8 [1]."]], "4": [["Q5", "C − 5 = 12n [1]; n = (C − 5)/12 [1]."], ["Q6", "2 < x ≤ 6; −1 ≤ x < 4; x > 3."]], "5": [["Q7", "Brother x, Amina 3x: 3x + 4 = 2(x + 4) [1]; 3x + 4 = 2x + 8 so x = 4 [1]; the brother is 4 and Amina is 12 [1]."]], "6": [["Exit ticket", "4(2x + 5)."]]}, "labels": {"q3_1": "Q4", "q4_0": "Q5", "q5_0": "Q7", "q6_0": "Exit ticket", "s6rev": "Revision plan", "s6q": "Question"}, "questions": {"Q1": "Expression, formula or equation?", "Q2": "Expand or factorise.", "Q3": "Solve.", "Q4": "The perimeter of a rectangle is 46 cm. Its length is (x + 7) cm and its width is x cm. Form and solve an equation to find x.", "Q5": "Make n the subject of C = 12n + 5.", "Q6": "Which inequality?", "Q7": "Amina is 3 times as old as her brother. In 4 years she will be twice as old as him. Form and solve an equation to find their ages now."}}'::jsonb, now()) on conflict (lesson) do update set title = excluded.title, spec = excluded.spec, updated_at = now();
insert into public.quizzes (id, topic_id, title, instructions, time_limit_minutes, max_attempts, published, show_results, category, feedback_mode, created_by) values ('b4b8ef9f-5b78-5f48-8f15-e4429df26f50', '35631a94-33f8-5eb8-b496-60f0301dee2d', 'Stage 8 Mathematics · Unit 5 Expressions, formulae and equations · Checkpoint-style questions', 'Checkpoint-style questions for Stage 8 Mathematics, Unit 5 Expressions, formulae and equations (objectives 8Ae.01, 8Ae.02, 8Ae.03, 8Ae.04, 8Ae.05, 8Ae.06, 8Ae.07), written in the style of the Cambridge Lower Secondary Checkpoint papers. 8 marks. Do the lesson first. Written answers are marked against the mark scheme and you get detailed feedback; your teacher checks every mark.', null, 2, true, true, 'quiz', 'hybrid', 'a9774d11-5d83-4bae-8da1-a6fb81c7dd7e') on conflict (id) do update set title = excluded.title, instructions = excluded.instructions, topic_id = excluded.topic_id;
