insert into public.lessons (id, topic_id, title, summary, url, external_id, max_marks, minutes, sort_order) values ('da6f438a-f428-5e62-a5d2-e3c26e2b8a29', '6fdea310-e655-51ea-8267-1bcda8124843', 'Unit 6 Sequences, functions and graphs: Sequences, functions and straight-line graphs', 'Stage 8 Mathematics · Objectives 8As.01, 8As.02, 8As.03, 8As.04, 8As.05, 8As.06, 8As.07', '/cks8-maths-6/', 'CKS8-MATHS-L6', 17, 60, 60) on conflict (external_id) do update set title = excluded.title, summary = excluded.summary, url = excluded.url, max_marks = excluded.max_marks, minutes = excluded.minutes, topic_id = excluded.topic_id, sort_order = excluded.sort_order;
insert into public.lesson_specs (lesson, title, spec, updated_at) values ('CKS8-MATHS-L6', 'Unit 6 Sequences, functions and graphs: Sequences, functions and straight-line graphs', '{"marks": {"1": [{"kind": "choice", "id": "q1_0", "q": "Q1", "max": 4, "n": 4, "ans": ["3n + 1", "5n − 2", "2n + 7", "20 − 4n"], "tip": "Difference, then adjust."}], "2": [{"kind": "text", "id": "q2_0", "q": "Q2", "max": 2, "pts": [["21"], ["7"]], "tips": ["Forwards, then backwards."]}], "3": [{"kind": "choice", "id": "q3_0", "q": "Q3", "max": 4, "n": 4, "ans": ["m = 2, c = 1", "m = −3, c = 4", "m = 1/2, c = 0", "m = 1, c = −5"], "tip": "Read m and c."}, {"kind": "text", "id": "q3_1", "q": "Q4", "max": 2, "pts": [["−2, 1, 4", "-2, 1, 4", "-2,1,4", "−2,1,4"], ["3"]], "tips": ["Substitute."]}], "4": [{"kind": "text", "id": "q4_0", "q": "Q5", "max": 2, "pts": [["a", "17"], ["3", "20 − 17", "$3"]], "tips": ["Substitute x = 6."]}], "5": [{"kind": "text", "id": "q5_0", "q": "Q6", "max": 3, "pts": [["4", "gradient"], ["y = 4x + 3", "y=4x+3"], ["yes", "23"]], "tips": ["Gradient, intercept, check."]}]}, "models": {"1": [["Q1", "3n + 1; 5n − 2; 2n + 7; 20 − 4n."]], "2": [["Q2", "4 × 6 − 3 = 21 [1]; (25 + 3) ÷ 4 = 7 [1]."]], "3": [["Q3", "m = 2, c = 1; m = −3, c = 4; m = 1/2, c = 0; m = 1, c = −5."], ["Q4", "y = −2, 1, 4 [1]; gradient 3 [1]."]], "4": [["Q5", "Plan A: 2 × 6 + 5 = $17; plan B: 3 × 6 + 2 = $20 [1]; plan A is cheaper by $3 [1]."]], "5": [["Q6", "Gradient = (11 − 3) ÷ 2 = 4 [1]; y = 4x + 3 [1]; when x = 5, y = 23, so yes, it lies on the line [1]."]], "6": [["Exit ticket", "−3."]]}, "labels": {"q2_0": "Q2", "q3_1": "Q4", "q4_0": "Q5", "q5_0": "Q6", "q6_0": "Exit ticket", "s6rev": "Revision plan", "s6q": "Question"}, "questions": {"Q1": "nth term?", "Q2": "A function is \"multiply by 4 then subtract 3\". Find the output when the input is 6, and the input when the output is 25.", "Q3": "Gradient and intercept.", "Q4": "Complete a table for y = 3x − 2 for x = 0, 1, 2 and state the gradient.", "Q5": "Use the plans above. Which plan is cheaper for 6 GB, and by how much?", "Q6": "A line passes through (0, 3) and (2, 11). Find its equation and decide whether (5, 23) lies on it."}}'::jsonb, now()) on conflict (lesson) do update set title = excluded.title, spec = excluded.spec, updated_at = now();
