insert into public.lessons (id, topic_id, title, summary, url, external_id, max_marks, minutes, sort_order) values ('06124889-0acf-5ecd-adc3-2c9195e1114b', '8bb31eb6-c56f-5c3c-a2e5-4573a6eb30e7', 'Unit 7 Shapes, area, volume and angles: Shapes, area, volume and angles', 'Stage 8 Mathematics · Objectives 8Gg.01, 8Gg.02, 8Gg.03, 8Gg.04, 8Gg.05, 8Gg.06, 8Gg.07, 8Gg.08, 8Gg.09, 8Gg.10, 8Gg.11, 8Gg.12', '/cks8-maths-7/', 'CKS8-MATHS-L7', 17, 60, 70) on conflict (external_id) do update set title = excluded.title, summary = excluded.summary, url = excluded.url, max_marks = excluded.max_marks, minutes = excluded.minutes, topic_id = excluded.topic_id, sort_order = excluded.sort_order;
insert into public.lesson_specs (lesson, title, spec, updated_at) values ('CKS8-MATHS-L7', 'Unit 7 Shapes, area, volume and angles: Shapes, area, volume and angles', '{"marks": {"1": [{"kind": "choice", "id": "q1_0", "q": "Q1", "max": 4, "n": 4, "ans": ["True", "False", "True", "True"], "tip": "Use the hierarchy."}], "2": [{"kind": "choice", "id": "q2_0", "q": "Q2", "max": 4, "n": 4, "ans": ["24 cm²", "35 cm²", "31.4 cm", "40 km"], "tip": "Use the formulae."}], "3": [{"kind": "text", "id": "q3_0", "q": "Q3", "max": 2, "pts": [["12", "½ × 6 × 4"], ["120"]], "tips": ["Triangle area × length."]}, {"kind": "text", "id": "q3_1", "q": "Q4", "max": 2, "pts": [["5 + 5 − e = 2", "5+5-e=2", "10 − e", "f + v − e"], ["8"]], "tips": ["F + V − E = 2."]}], "4": [{"kind": "text", "id": "q4_0", "q": "Q5", "max": 2, "pts": [["115"], ["sum", "opposite", "exterior angle"]], "tips": ["Exterior = sum of opposite interior."]}], "5": [{"kind": "text", "id": "q5_0", "q": "Q7", "max": 3, "pts": [["½ × 30 × 10", "15 × 10", "150"], ["6"], ["6 bags"]], "tips": ["Area, then divide."]}]}, "models": {"1": [["Q1", "Squares are rectangles but not the reverse; rhombuses are parallelograms; a regular hexagon has 6 lines."]], "2": [["Q2", "24; ½ × 14 × 5 = 35; 31.4; 25 ÷ 5 × 8 = 40."]], "3": [["Q3", "Triangle area = ½ × 6 × 4 = 12 cm² [1]; volume = 12 × 10 = 120 cm³ [1]."], ["Q4", "5 + 5 − E = 2 [1], so E = 8 [1]."]], "4": [["Q5", "115° [1] because the exterior angle equals the sum of the two opposite interior angles (50° + 65°) [1]."], ["Q6", "Draw 7 cm base; arc 5 cm from one end and 6 cm from the other; join to the crossing point."]], "5": [["Q7", "Area = ½(12 + 18) × 10 = 150 m² [1]; 150 ÷ 25 = 6 [1]; 6 bags are needed [1]."]], "6": [["Exit ticket", "A = ½(a + b)h."]]}, "labels": {"q3_0": "Q3", "q3_1": "Q4", "q4_0": "Q5", "q4_1": "Q6", "q5_0": "Q7", "q6_0": "Exit ticket", "s6rev": "Revision plan", "s6q": "Question"}, "questions": {"Q1": "True or false?", "Q2": "Calculate.", "Q3": "A triangular prism has a triangular cross-section with base 6 cm and height 4 cm, and a length of 10 cm. Calculate its volume.", "Q4": "A square-based pyramid has 5 faces and 5 vertices. Use Euler''s formula to find the number of edges.", "Q5": "A triangle has interior angles of 50° and 65°. Find the exterior angle at the third vertex and give a reason.", "Q6": "In your book, construct a triangle with sides 7 cm, 5 cm and 6 cm using a ruler and compasses. Describe your steps.", "Q7": "A trapezium-shaped garden has parallel sides 12 m and 18 m and is 10 m wide. Grass seed covers 25 m² per bag. How many bags are needed?"}}'::jsonb, now()) on conflict (lesson) do update set title = excluded.title, spec = excluded.spec, updated_at = now();
