insert into public.lesson_specs (lesson, title, spec, updated_at) values ('CKS8-MATHS-L8', 'Unit 8 Position and transformation: Bearings, vectors and transformations', '{"marks": {"1": [{"kind": "choice", "id": "q1_0", "q": "Q1", "max": 4, "n": 4, "ans": ["090°", "225°", "315°", "310°"], "tip": "Clockwise from north."}], "2": [{"kind": "choice", "id": "q2_0", "q": "Q2", "max": 4, "n": 4, "ans": ["(5, 3)", "(0, 2)", "(−1, −4)", "(3.5, 6)"], "tip": "Average each coordinate."}], "3": [{"kind": "choice", "id": "q3_0", "q": "Q3", "max": 4, "n": 4, "ans": ["(5, 1)", "(1, 3)", "(−1, −3)", "(1, −1)"], "tip": "Move or swap."}], "4": [{"kind": "text", "id": "q4_0", "q": "Q4", "max": 2, "pts": [["90"], ["anticlockwise", "anti-clockwise", "origin", "(0, 0)"]], "tips": ["Angle, direction, centre."]}, {"kind": "text", "id": "q4_1", "q": "Q5", "max": 2, "pts": [["(2, 2)", "(2,2)"], ["(4, 2)", "(2, 6)", "(4,2)", "(2,6)"]], "tips": ["Multiply each coordinate."]}], "5": [{"kind": "text", "id": "q5_0", "q": "Q6", "max": 3, "pts": [["16 + 9", "25", "4² + 3²"], ["5"], ["037", "37", "036.9", "between"]], "tips": ["Pythagoras, then bearing."]}]}, "models": {"1": [["Q1", "090°; 225°; 315°; 130 + 180 = 310°."]], "2": [["Q2", "(5, 3); (0, 2); (−1, −4); (3.5, 6)."]], "3": [["Q3", "(5, 1); (1, 3); (−1, −3); (1, −1)."]], "4": [["Q4", "A rotation of 90° [1] anticlockwise about the origin (0, 0) [1]."], ["Q5", "(2, 2) [1], (4, 2) and (2, 6) [1]."]], "5": [["Q6", "AC² = 4² + 3² = 25 [1], so AC = 5 km [1]; C is north-east of A, on a bearing of about 037° [1]."]], "6": [["Exit ticket", "180°."]]}, "labels": {"q4_0": "Q4", "q4_1": "Q5", "q5_0": "Q6", "q6_0": "Exit ticket", "s6rev": "Revision plan", "s6q": "Question"}, "questions": {"Q1": "Write the bearing.", "Q2": "Find the midpoint.", "Q3": "Where does the point go?", "Q4": "Describe fully the rotation that maps (2, 0) to (0, 2) about the origin.", "Q5": "A triangle has vertices (1, 1), (2, 1), (1, 3). Enlarge it by scale factor 2 from the origin. 