insert into public.lesson_specs (lesson, title, spec, updated_at) values ('CKS8-MATHS-L9', 'Unit 9 Statistics: Collecting, presenting and comparing data', '{"marks": {"1": [{"kind": "choice", "id": "q1_0", "q": "Q1", "max": 3, "n": 3, "ans": ["Systematic", "Random", "Biased"], "tip": "How are people chosen?"}], "2": [{"kind": "choice", "id": "q2_0", "q": "Q2", "max": 4, "n": 4, "ans": ["Pie chart", "Stem-and-leaf diagram", "Frequency diagram", "Scatter graph"], "tip": "Data type."}], "3": [{"kind": "choice", "id": "q3_0", "q": "Q3", "max": 4, "n": 4, "ans": ["7", "8", "9", "14"], "tip": "Order first."}], "4": [{"kind": "text", "id": "q4_0", "q": "Q4", "max": 2, "pts": [["x+more", "x read more", "x higher"], ["y+consistent", "y less spread", "y smaller range"]], "tips": ["Average and spread."]}], "5": [{"kind": "text", "id": "q5_0", "q": "Q5", "max": 3, "pts": [["random", "sample"], ["hours", "books", "reading", "vocabulary", "test"], ["scatter"]], "tips": ["Sample, data, graph."]}]}, "models": {"1": [["Q1", "Every 5th: systematic; hat: random; friends: biased."]], "2": [["Q2", "Pie; stem-and-leaf; frequency diagram; scatter."]], "3": [["Q3", "Mode 7; median 8; mean 9; range 14."]], "4": [["Q4", "Class X read more books on average (higher mean) [1]; Class Y was more consistent (smaller range) [1]."]], "5": [["Q5", "Take a random sample of about 30 students from all classes [1]; record how many hours each reads per week and their vocabulary test score [1]; draw a scatter graph to look for a correlation [1]."]], "6": [["Exit ticket", "5."]]}, "labels": {"q4_0": "Q4", "q5_0": "Q5", "q6_0": "Exit ticket", "s6rev": "Revision plan", "s6q": "Question"}, "questions": {"Q1": "Name the sampling method.", "Q2": "Best representation?", "Q3": "For 4, 7, 7, 8, 9, 10, 18, find:", "Q4": "Class X: mean 15 books read, range 22. Class Y: mean 12 books read, range 6. Compare the two classes.", "Q5": "Plan an investigation into whether students who read more have a larger vocabulary. Include sampling, data and the graph you would draw."}}'::jsonb, now()) on conflict (lesson) do update set title = excluded.title, spec = excluded.spec, updated_at = now();
