insert into public.lesson_specs (lesson, title, spec, updated_at) values ('CKS8-MATHS-L10', 'Unit 10 Probability: Probability of combined events', '{"marks": {"1": [{"kind": "choice", "id": "q1_0", "q": "Q1", "max": 4, "n": 4, "ans": ["0.65", "5/6", "0.92", "3/7"], "tip": "1 − P."}], "2": [{"kind": "choice", "id": "q2_0", "q": "Q2", "max": 4, "n": 4, "ans": ["1/12", "1/4", "1/2", "1/6"], "tip": "Count from the 12 outcomes."}], "3": [{"kind": "text", "id": "q3_0", "q": "Q3", "max": 2, "pts": [["4+6", "5+5", "6+4", "3 ways", "three"], ["3/36", "1/12"]], "tips": ["List the pairs."]}], "4": [{"kind": "text", "id": "q4_0", "q": "Q4", "max": 3, "pts": [["20/60", "1/3"], ["1/6", "10"], ["biased", "more trials", "unfair"]], "tips": ["Compare 1/3 with 1/6."]}], "5": [{"kind": "text", "id": "q5_0", "q": "Q5", "max": 3, "pts": [["16", "sample space", "table"], ["8", "even", "odd"], ["fair", "equal", "1/2"]], "tips": ["Count even and odd totals."]}]}, "models": {"1": [["Q1", "0.65; 5/6; 0.92; 3/7."]], "2": [["Q2", "1/12; 3/12 = 1/4; 6/12 = 1/2; 2/12 = 1/6."]], "3": [["Q3", "(4, 6), (5, 5), (6, 4): 3 ways [1]; P = 3/36 = 1/12 [1]."]], "4": [["Q4", "Experimental P(6) = 20/60 = 1/3 [1]; theoretical P(6) = 1/6, so we would expect about 10 sixes [1]; this suggests the dice may be biased, but more trials would make the conclusion more reliable [1]."]], "5": [["Q5", "There are 16 equally likely outcomes [1]; 8 give an even total and 8 give an odd total [1]; P(A) = P(B) = 1/2, so the game is fair [1]."]], "6": [["Exit ticket", "0.7."]]}, "labels": {"q3_0": "Q3", "q4_0": "Q4", "q5_0": "Q5", "q6_0": "Exit ticket", "s6rev": "Revision plan", "s6q": "Question"}, "questions": {"Q1": "Find the probability.", "Q2": "Coin and dice. Find:", "Q3": "Two fair dice are rolled and the scores added. Find P(total = 10). Show how you counted.", "Q4": "A dice is rolled 60 times and lands on 6 twenty times. Calculate the experimental probability of a 6, compare it with the theoretical probability, and suggest a conclusion.", "Q5": "Two spinners, each numbered 1 to 4, are spun and the numbers added. Player A wins on an even total, player B on an odd total. Is the game fair? Explain with a sample space."}}'::jsonb, now()) on conflict (lesson) do update set title = excluded.title, spec = excluded.spec, updated_at = now();
