insert into public.questions (id, kind, prompt, options, marks, section, created_by) values ('870a279c-b318-50f3-b4a5-d81f108f94b5', 'short', '8. Magnesium is put into copper sulfate solution. Write the word equation and explain why a reaction happens.', '[]'::jsonb, 3, 'Paper 1', 'a9774d11-5d83-4bae-8da1-a6fb81c7dd7e') on conflict (id) do update set prompt = excluded.prompt, options = excluded.options, marks = excluded.marks, kind = excluded.kind, section = excluded.section;
insert into public.question_answers (question_id, model_answer, mark_scheme, points, explanation) values ('870a279c-b318-50f3-b4a5-d81f108f94b5', 'magnesium + copper sulfate → magnesium sulfate [1] + copper [1]; magnesium is more reactive than copper, so it displaces it [1].', 'magnesium + copper sulfate → magnesium sulfate [1] + copper [1]; magnesium is more reactive than copper, so it displaces it [1].', '[{"text": "Magnesium + copper sulfate → magnesium sulfate", "any": ["magnesium sulfate"], "all": [], "marks": 1}, {"text": "+ copper", "any": ["copper"], "all": [], "marks": 1}, {"text": "Magnesium is more reactive than copper, so it displaces it", "any": ["more reactive"], "all": [], "marks": 1}]'::jsonb, 'magnesium + copper sulfate → magnesium sulfate [1] + copper [1]; magnesium is more reactive than copper, so it displaces it [1].') on conflict (question_id) do update set model_answer = excluded.model_answer, mark_scheme = excluded.mark_scheme, points = excluded.points, explanation = excluded.explanation;
