insert into public.question_answers (question_id, model_answer, mark_scheme, points, explanation) values ('b2a15943-a2d5-56ca-8638-2aedeb3f8359', 'Add excess copper oxide to warm acid [1]; filter off the unreacted solid [1]; evaporate some water and leave to crystallise, then dry [1].', 'Add excess copper oxide to warm acid [1]; filter off the unreacted solid [1]; evaporate some water and leave to crystallise, then dry [1].', '[{"text": "Add excess copper oxide to warm acid", "any": ["excess", "add copper oxide"], "all": [], "marks": 1}, {"text": "Filter off the unreacted solid", "any": ["filter"], "all": [], "marks": 1}, {"text": "Evaporate some water and leave to crystallise, then dry", "any": ["evaporate", "crystallise", "heat"], "all": [], "marks": 1}]'::jsonb, 'Add excess copper oxide to warm acid [1]; filter off the unreacted solid [1]; evaporate some water and leave to crystallise, then dry [1].') on conflict (question_id) do update set model_answer = excluded.model_answer, mark_scheme = excluded.mark_scheme, points = excluded.points, explanation = excluded.explanation;
