insert into public.questions (id, kind, prompt, options, marks, section, created_by) values ('34702190-963c-5347-8c11-28ef0fc1bfbd', 'short', '1. A cyclist travels 4.5 km in 15 minutes. Calculate the average speed in m/s.', '[]'::jsonb, 3, 'Paper 1', 'a9774d11-5d83-4bae-8da1-a6fb81c7dd7e') on conflict (id) do update set prompt = excluded.prompt, options = excluded.options, marks = excluded.marks, kind = excluded.kind, section = excluded.section;
insert into public.question_answers (question_id, model_answer, mark_scheme, points, explanation) values ('34702190-963c-5347-8c11-28ef0fc1bfbd', '4.5 km = 4500 m [1]; 15 min = 900 s [1]; 4500 ÷ 900 = 5 m/s [1].', '4.5 km = 4500 m [1]; 15 min = 900 s [1]; 4500 ÷ 900 = 5 m/s [1].', '[{"text": "4.5 km = 4500 m", "any": ["4500"], "all": [], "marks": 1}, {"text": "15 min = 900 s", "any": ["900"], "all": [], "marks": 1}, {"text": "4500 ÷ 900 = 5 m/s", "any": ["5"], "all": [], "marks": 1}]'::jsonb, '4.5 km = 4500 m [1]; 15 min = 900 s [1]; 4500 ÷ 900 = 5 m/s [1].') on conflict (question_id) do update set model_answer = excluded.model_answer, mark_scheme = excluded.mark_scheme, points = excluded.points, explanation = excluded.explanation;
