insert into public.questions (id, kind, prompt, options, marks, section, created_by) values ('c0c488aa-7c45-5a8a-b73b-f1b918a4beb4', 'short', '3. A 400 N child sits 1.5 m from the pivot of a see-saw. How far from the pivot must a 600 N adult sit to balance it?', '[]'::jsonb, 3, 'Paper 1', 'a9774d11-5d83-4bae-8da1-a6fb81c7dd7e') on conflict (id) do update set prompt = excluded.prompt, options = excluded.options, marks = excluded.marks, kind = excluded.kind, section = excluded.section;
insert into public.question_answers (question_id, model_answer, mark_scheme, points, explanation) values ('c0c488aa-7c45-5a8a-b73b-f1b918a4beb4', 'Child''s moment = 400 × 1.5 = 600 N m [1]; adult''s moment must equal this, so distance = 600 ÷ 600 [1] = 1 m [1].', 'Child''s moment = 400 × 1.5 = 600 N m [1]; adult''s moment must equal this, so distance = 600 ÷ 600 [1] = 1 m [1].', '[{"text": "Child''s moment = 400 × 1.5 = 600 N m", "any": ["600", "400 × 1.5", "400×1.5"], "all": [], "marks": 1}, {"text": "Adult''s moment must equal this, so distance = 600 ÷ 600", "any": ["600 ÷ 600", "moment"], "all": [], "marks": 1}, {"text": "= 1 m", "any": ["1"], "all": [], "marks": 1}]'::jsonb, 'Child''s moment = 400 × 1.5 = 600 N m [1]; adult''s moment must equal this, so distance = 600 ÷ 600 [1] = 1 m [1].') on conflict (question_id) do update set model_answer = excluded.model_answer, mark_scheme = excluded.mark_scheme, points = excluded.points, explanation = excluded.explanation;
