insert into public.question_answers (question_id, model_answer, mark_scheme, points, explanation) values ('0c1d9f22-44d6-5df5-9ead-75f8ea7206e1', 'P = F ÷ A = 1200 ÷ 0.4 [1] = 3000 Pa (N/m²) [1].', 'P = F ÷ A = 1200 ÷ 0.4 [1] = 3000 Pa (N/m²) [1].', '[{"text": "P = F ÷ A = 1200 ÷ 0.4", "any": ["1200 ÷ 0.4", "1200/0.4"], "all": [], "marks": 1}, {"text": "= 3000 Pa (N/m²)", "any": ["3000"], "all": [], "marks": 1}]'::jsonb, 'P = F ÷ A = 1200 ÷ 0.4 [1] = 3000 Pa (N/m²) [1].') on conflict (question_id) do update set model_answer = excluded.model_answer, mark_scheme = excluded.mark_scheme, points = excluded.points, explanation = excluded.explanation;
